'use strict';
(function(){
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('near','Near continues Old English near, the comparative form of neah (“nigh”); it describes closeness in place or time, a close relationship, or movement toward a point.',[C('near.s1','空间位置','The field station is near the river, so researchers can collect water samples before the morning current strengthens.','野外站靠近河边，研究人员能在早晨水流增强前采集水样。','The field station is near the river / so researchers can collect water samples / before the morning current strengthens.','near 作介词表示离某处不远。','站点与河流距离短，便于取样。'),C('near.s2','大约接近','The repair cost came near to two thousand pounds, although the final invoice was slightly lower.','维修费接近两千英镑，不过最后的账单略低一些。','The repair cost came near to two thousand pounds / although the final invoice / was slightly lower.','near 可表示数值或程度“接近、差不多”。','账单接近但没有达到两千英镑。'),C('near.s3','关系或临近','A near friend called just before the deadline, and the near-complete report was ready by noon.','一位亲密朋友在截止日期前打来电话，接近完成的报告中午前也准备好了。','A near friend called just before the deadline / and the near-complete report / was ready by noon.','near 作形容词可表示亲近，也可表示即将完成或发生。','friend 表关系亲近，near-complete 表接近完成。'),C('near.s4','逐渐靠近','As winter neared, the mountain road closed at dusk because ice formed quickly in the shaded bends.','冬季临近时，山路黄昏便关闭，因为阴影弯道很快结冰。','As winter neared / the mountain road closed at dusk / because ice formed quickly in the shaded bends.','near 作动词表示在时间或空间上逐渐接近。','季节接近冬季，触发道路防冻措施。')],M('The station is near the river, meaning it is several hundred kilometres away and cannot reach the water.','The station is near the river, only a short walk from the bank.','near 表示距离短；数百公里外不能称为靠近河岸。','meaning'),[q('Why can researchers collect samples easily?','the station is close to the river','the river is several countries away','the station is on a different planet','near the river 表示野外站离河岸不远。',1),q('How did the repair cost compare with £2,000?','it was close to that amount but a little lower','it was exactly £200','it was thousands of pounds higher','账单接近两千英镑但略低。',2,'measurement'),q('In near friend, near describes?','a close personal relationship','movement toward a place','an exact clock time','near 作形容词可表示关系亲密。',3,'distinction'),q('What does winter neared mean?','winter was approaching','winter had ended','winter stayed at the same distance','near 作动词表示逐渐临近。',4,'grammar')]);
P('nearby','Nearby combines near and by; it describes a place a short distance from a stated location, or means “in the vicinity.”',[C('nearby.s1','邻近地点','A nearby clinic kept its doors open after the flood, giving residents a place to collect clean drinking water.','洪水后，附近的一家诊所继续开放，为居民提供取用干净饮用水的地点。','A nearby clinic kept its doors open after the flood / giving residents a place / to collect clean drinking water.','nearby 作形容词，通常放在名词前表示地点邻近。','clinic 紧邻居民区，能提供就近帮助。'),C('nearby.s2','在附近','We searched the loading yard and nearby for the missing tool before ordering a replacement.','下单补购前，我们搜查了装货场以及附近区域，寻找丢失的工具。','We searched the loading yard / and nearby / for the missing tool / before ordering a replacement.','nearby 也可作副词，表示在附近。','nearby 独立指装货场周围区域。')],M('The team called a clinic on the other side of the country nearby to the flooded village.','The team called a clinic a few streets from the flooded village nearby.','相隔全国的地点不在村庄附近。'),[q('What did the nearby clinic provide?','clean drinking water','a mountain road','a motor race','洪水后诊所提供干净饮用水。'),q('Where did the team look besides the yard?','in the surrounding area','inside a distant country','under the river','nearby 作副词指装货场周围。',2),q('In a nearby clinic, nearby is?','an adjective modifying clinic','a verb meaning to search','a plural noun','nearby 位于名词 clinic 前作形容词。',1,'grammar'),q('Which location is nearby to the village?','a clinic a few streets away','a clinic hundreds of miles away','a hospital on another continent','短距离地点才称 nearby。',1,'context')]);
P('nearest','Nearest is the superlative of near and means closest in space, time, or relationship among the compared choices.',C('nearest.s1','最近选项','Of the three pharmacies, the one beside the station is nearest to the hotel and stays open until midnight.','三家药店中，车站旁那家离酒店最近，而且营业到午夜。','Of the three pharmacies / the one beside the station is nearest to the hotel / and stays open until midnight.','nearest 表示在三者或更多对象中距离最短。','三家药店比较后，车站旁的一家最近。'),M('The guide chose the nearest pharmacy, which was farther from the hotel than the other two.','The guide chose the pharmacy beside the station, the closest of the three to the hotel.','最远的一家不能称为 nearest。','distinction'),[q('Which pharmacy is nearest to the hotel?','the one beside the station','the one across the county','all three at equal distance','站旁药店是三家中最近的。'),q('What time does the nearest pharmacy stay open until?','midnight','noon','sunrise','例句给出营业至午夜。',1,'measurement'),q('Nearest is the superlative form of?','near','nearby','nearly','nearest 比较距离，源自 near 的最高级。',1,'word-formation'),q('If one shop is nearest, it is?','closer than the other compared shops','farther than all the others','exactly the same distance as every shop','最高级表示在比较组中最靠近。',1,'meaning')]);
P('nearly','Nearly is near plus -ly and means almost, but usually not completely or exactly.',C('nearly.s1','接近完成','The crew had nearly finished painting the bridge when rain began, leaving only the final rail uncovered.','开始下雨时，工人几乎已完成桥梁涂装，只剩最后一段栏杆未刷。','The crew had nearly finished painting the bridge / when rain began / leaving only the final rail uncovered.','nearly 修饰 finished，表示接近完成但尚未全部完成。','最后一段尚未涂装，因此只是几乎完成。'),M('The crew had nearly finished the bridge, meaning every rail had been painted and all work was completely done.','The crew had nearly finished the bridge, with one final rail still unpainted.','nearly 通常保留少量尚未完成的部分，不等于完全做完。','meaning'),[q('What remained when the rain began?','the final rail still needed painting','the entire bridge was untouched','a new river had appeared','例句明确还剩最后一段栏杆。'),q('Nearly finished means?','almost finished but not fully finished','not started at all','completed exactly on time','nearly 表示几乎完成而未完全完成。',1),q('Which result is nearly complete?','99 of 100 pages are checked','none of 100 pages is checked','all pages were checked yesterday','几乎全部完成但仍差一页。',1,'measurement'),q('Nearly is closest in meaning to?','almost','never','exactly','nearly 意为“几乎、将近”。',1,'confusable')]);
P('nearly all','Nearly all is a quantifying phrase meaning almost every member or almost the whole amount, while allowing a few exceptions.',C('nearly all.s1','大多数成员','Nearly all the seedlings survived the cold night, though two of the youngest plants wilted by morning.','几乎所有幼苗都熬过了寒夜，不过最小的两株到早晨时枯萎了。','Nearly all the seedlings survived the cold night / though two of the youngest plants / wilted by morning.','nearly all + 复数名词表示几乎每一个，仍允许少量例外。','两株枯萎说明并非绝对全部存活。'),M('Nearly all the seedlings survived, meaning every single one died before morning.','Nearly all the seedlings survived; only two of the youngest wilted.','nearly all 表示几乎全体，不能解释为全部死亡。','meaning'),[q('How many seedlings wilted?','two of the youngest','all of them','none had been planted','少数两株到早晨枯萎。',1,'measurement'),q('Does nearly all mean absolutely every one?','no, a few exceptions may remain','yes, it excludes every exception','no, it means almost none','nearly all 允许存在少数例外。',1,'distinction'),q('Which sentence uses nearly all accurately?','Nearly all the forms were signed, but three were still blank.','Nearly all the forms were signed, so none was signed.','Nearly all one form were signed.','几乎全部签署但仍有三份空白，符合短语含义。',1,'grammar'),q('What does nearly all the seedlings quantify?','almost the entire group of seedlings','only the two that wilted','a single seedling only','短语限定的是整组幼苗中的绝大部分。',1,'meaning')]);
P('nearness','Nearness is near plus -ness and names closeness in distance, time, or personal connection.',[C('nearness.s1','空间接近','The nearness of the railway station made the apartment convenient for commuters who did not own cars.','火车站近在咫尺，使这套公寓对没有汽车的通勤者很方便。','The nearness of the railway station / made the apartment convenient / for commuters who did not own cars.','nearness 是名词，指距离上的接近。','交通站点距离短，节省通勤时间。'),C('nearness.s1','关系亲近','Their nearness grew over years of working together, until each trusted the other with difficult decisions.','多年共事让两人的关系日渐亲近，最后彼此都能托付艰难决定。','Their nearness grew over years of working together / until each trusted the other / with difficult decisions.','nearness 也可指人与人之间的亲密关系。','信任体现两人关系亲近。')],M('The nearness of the station made the flat convenient even though the platform was several hours away by car.','The nearness of the station made the flat convenient because it was a short walk away.','相隔数小时车程不是空间上的接近。','meaning'),[q('Why was the apartment convenient?','the station was close by','the residents all owned cars','the station was across the country','火车站离公寓近。'),q('What showed the colleagues’ nearness?','they trusted each other with difficult decisions','they had never met','they lived several countries apart','彼此信任表明关系亲近。',1),q('Nearness can refer to?','short distance or close personal connection','only a superlative comparison','a type of necklace','nearness 有空间和关系两种接近义。',1,'distinction'),q('Nearness is formed from near plus?','-ness','-ly','-able','-ness 把形容词 near 变成抽象名词。',1,'word-formation')]);
P('neat','Neat came through Middle English from Old French net, “clean”; it can mean tidy, elegantly simple, or (of a drink) unmixed.',[C('neat.s1','整齐干净','She kept the workshop neat by returning each wrench to its labelled drawer after repairing a bicycle.','她修好自行车后把每把扳手放回贴有标签的抽屉，使工作间保持整洁。','She kept the workshop neat / by returning each wrench / to its labelled drawer / after repairing a bicycle.','neat 作形容词表示干净整齐、物品各归其位。','工具收纳有序使工作间整洁。'),C('neat.s2','简洁巧妙','The engineer found a neat solution: a single hinged panel concealed the cables and still allowed quick access.','工程师想出一个巧妙简洁的办法：用一块铰接面板藏住电缆，同时方便快速检修。','The engineer found a neat solution / a single hinged panel concealed the cables / and still allowed quick access.','neat 也可称赞简洁而巧妙的办法或熟练利落的动作。','一个简单装置兼顾隐藏和检修。'),C('neat.s3','酒不掺水','He ordered the whisky neat, without ice or water, and sipped it slowly after dinner.','他点了一杯纯威士忌，不加冰也不兑水，晚饭后慢慢品尝。','He ordered the whisky neat / without ice or water / and sipped it slowly after dinner.','饮品 neat 表示不掺水或其他饮料。','without ice or water 明确说明纯饮。')],M('He ordered the whisky neat, meaning it was mixed with a large amount of water and soda.','He ordered the whisky neat, with no water or other mixer added.','饮品 neat 指纯饮、不掺水或混合饮料。','distinction'),[q('How did she keep the workshop neat?','she returned tools to labelled drawers','she scattered wrenches on the floor','she poured whisky on the bench','工具放回标记抽屉使工作间整齐。',1),q('What made the engineer’s solution neat?','one panel hid cables while allowing access','it required a maze of extra parts','it blocked every cable permanently','该设计简洁且兼顾检修。',2),q('What does whisky neat contain?','no water or mixer','mostly soda','a full glass of ice','纯饮不加水或其他调饮。',3,'distinction'),q('Which use means tidy rather than clever or undiluted?','a neat workshop','a neat solution','whisky neat','workshop 的 neat 表示整齐。',1,'distinction')]);
P('neaten','Neaten is neat plus the verb-forming suffix -en and means to make something tidier or more orderly.',C('neaten.s1','整理外观','Before the inspection, the caretaker neatened the library shelves and aligned the labels so each book was easy to find.','检查前，管理员整理了图书馆书架并排齐标签，让每本书都容易找到。','Before the inspection / the caretaker neatened the library shelves / and aligned the labels / so each book was easy to find.','neaten 作及物动词，表示把某物整理得更整齐。','排齐书籍和标签让书架更有序。'),M('The caretaker neatened the shelves by scattering books across the floor and removing all labels.','The caretaker neatened the shelves by putting books in order and aligning their labels.','把书散落在地上会使书架更乱。','meaning'),[q('What did the caretaker neaten?','the library shelves','a glass of whisky','the railway station distance','管理员整理了图书馆书架。'),q('How did the shelves become neater?','books and labels were aligned','books were scattered on the floor','all labels were removed','整理和排齐使书架变整齐。',1),q('Which action means neaten the desk?','put the papers into labelled folders','throw every paper around the room','pour a drink on the desk','将文件分类收好会使桌面整洁。',1,'context'),q('What does -en do in neaten?','forms a verb meaning make neat','forms a person who is neat','marks a past-tense noun','-en 在此构成“使变整齐”的动词。',1,'word-formation')]);
P('neatly','Neatly is neat plus -ly; it means in an orderly way or with skill and economy.',[C('neatly.s1','整齐地','The tailor folded each uniform neatly and stacked the finished garments by size on the clean table.','裁缝把每套制服都整齐叠好，并按尺码堆放在干净的桌子上。','The tailor folded each uniform neatly / and stacked the finished garments by size / on the clean table.','neatly 修饰 folded，表示动作整齐有序。','叠放并按尺码排列呈现整洁。'),C('neatly.s1','巧妙利落地','The final sentence neatly resolves the mystery by connecting the torn map to the locked observatory.','最后一句巧妙地解开了谜团，把撕破的地图与上锁的天文台联系起来。','The final sentence neatly resolves the mystery / by connecting the torn map / to the locked observatory.','neatly 也可表示以简洁而有效的方式解决问题。','一个线索简明地串联了两件事。')],M('The tailor folded the uniforms neatly by leaving them crumpled in a heap on the floor.','The tailor folded the uniforms neatly and stacked them by size.','皱巴巴地堆在地上不符合整齐有序。'),[q('How were the finished uniforms arranged?','folded and stacked by size','left crumpled on the floor','mixed with the whisky','制服按尺码整齐叠放。'),q('How does the final sentence resolve the mystery?','it links the map to the observatory','it adds an unrelated character','it repeats the question without an answer','最后一句把地图线索与天文台联系起来。',1),q('Which task is done neatly?','folding shirts in straight stacks','throwing clothes into a heap','writing a sentence with no connection','整齐堆叠衣物是 neatly。',1,'context'),q('In neatly resolves the mystery, neatly means?','cleverly and economically','in a nearby place','almost completely','此处表示简洁巧妙地解决。',1,'distinction')]);
P('neatness','Neatness is neat plus -ness; it names tidy arrangement or, more broadly, simple and skillful execution.',[C('neatness.s1','整洁程度','The inspector praised the neatness of the storeroom, where every container had a label and a fixed shelf.','检查员称赞储藏室整洁有序，每个容器都有标签并放在固定架位上。','The inspector praised the neatness of the storeroom / where every container had a label / and a fixed shelf.','neatness 指整洁、物品井然有序的状态。','标签和固定位置体现储藏室的整洁。'),C('neatness.s2','简洁利落','The editor admired the neatness of the proof: one small change removed a repeated paragraph without losing any evidence.','编辑欣赏校样处理得简洁利落：一个小改动删去了重复段落，却没有丢失证据。','The editor admired the neatness of the proof / one small change removed a repeated paragraph / without losing any evidence.','neatness 也指简单巧妙、不浪费步骤的处理方式。','一次精简避免重复，同时保留信息。')],M('The inspector praised the storeroom’s neatness although boxes blocked the aisles and labels were scattered on the floor.','The inspector praised the storeroom’s neatness because containers were labelled and kept in fixed places.','通道被堵且标签散落，与整洁有序不符。','meaning'),[q('What showed the storeroom’s neatness?','labelled containers on fixed shelves','blocked aisles and loose labels','a whisky order','容器有标签且位置固定。'),q('What did the editor’s neat change accomplish?','removed repetition without losing evidence','deleted all supporting evidence','added another repeated paragraph','小改动删重复而保留证据。',2),q('Which use of neatness is about writing?','a concise edit that preserves the argument','a spotless storeroom shelf','a tidy row of containers','编辑校样的简洁处理属于第二义。',2,'distinction'),q('Neatness is the abstract noun of?','neat','neaten','nearby','neatness 由 neat 加 -ness 构成。',1,'word-formation')]);
P('nebula','Nebula comes from Latin nebula, “mist or cloud”; astronomy uses it for a vast cloud of gas and dust, and older usage applied it to cloudy-looking celestial or eye features.',[C('nebula.s1','星际云','The telescope revealed a nebula where hot young stars lit the surrounding gas and dust in vivid colours.','望远镜显示出一片星云，炽热的新生恒星把周围的气体和尘埃照亮成鲜艳色彩。','The telescope revealed a nebula / where hot young stars lit the surrounding gas and dust / in vivid colours.','现代天文学中 nebula 指太空中的巨大气体和尘埃云。','气体尘埃被恒星照亮，呈现星云景象。'),C('nebula.s2','云状天体旧义','In an early observing log, the astronomer called the faint fuzzy patch a nebula before later instruments resolved it into individual stars.','在早期观测日志中，天文学家把暗淡模糊的斑点称为 nebula，后来的仪器才将其分辨为单颗恒星。','In an early observing log / the astronomer called the faint fuzzy patch a nebula / before later instruments resolved it into individual stars.','旧义 nebula 可指望远镜中看似云雾的天体；旧医学也曾称眼部混浊斑为此名。','早期仪器未能分辨出模糊斑点中的恒星。')],M('The astronomer called a clearly resolved single planet a nebula because it was a cloud of interstellar gas and dust.','The astronomer called the diffuse cloud of interstellar gas and dust a nebula.','单颗行星不是由气体尘埃云组成的星云。','distinction'),[q('What lit the gas and dust in the observed nebula?','hot young stars','a nearby clinic','a whisky flame','新生恒星照亮星云物质。'),q('Why did the early log call the patch a nebula?','it looked fuzzy before instruments resolved its stars','it was already a clear single planet','it was a labelled shelf','早期仪器只能看到云雾状斑点。',2),q('What is a nebula in modern astronomy?','a large cloud of gas and dust in space','one clearly resolved planet','a tidy arrangement of stars on a shelf','现代天文学中是星际气体尘埃云。',1,'meaning'),q('Which sense is described as older usage?','a cloudy-looking celestial patch','a young star forming within a gas cloud','a telescope itself','旧用法可称云雾状天体斑点为 nebula。',2,'distinction')]);
P('nebular','Nebular is nebula plus -ar and means relating to a nebula or its cloud-like material.',C('nebular.s1','星云相关','The observatory measured nebular gas around the young stars to estimate how quickly the cloud was dispersing.','天文台测量年轻恒星周围的星云气体，以估算云团消散的速度。','The observatory measured nebular gas around the young stars / to estimate / how quickly the cloud was dispersing.','nebular 作形容词表示与星云有关。','被测气体属于恒星周围的星云。'),M('The astronomer described the empty space between galaxies as nebular gas even though no gas cloud was present.','The astronomer described the gas within the cloud surrounding the young stars as nebular gas.','没有气体云就没有可称为星云气体的物质。','word-choice'),[q('What did the observatory measure?','gas around young stars','the clinic’s water supply','a neatness score','天文台测量恒星周围的星云气体。'),q('Why measure the nebular gas?','to estimate how quickly the cloud was dispersing','to determine the hotel’s distance','to classify a necktie','测量是为了估算星云消散速度。',1),q('Nebular means?','related to a nebula','almost complete','located beside a station','nebular 是“星云的、与星云有关的”。',1,'meaning'),q('Nebular is formed from nebula plus?','-ar','-ness','-en','nebular 由 nebula 加 -ar 构成形容词。',1,'word-formation')]);
P('necessarily','Necessarily is necessary plus -ly; it means inevitably or as a logical consequence, often in the phrase not necessarily (“not always”).',C('necessarily.s1','不必然','A higher ticket price does not necessarily mean the concert costs more to produce; the venue may simply be smaller.','票价更高并不必然意味着演唱会制作成本更高；也可能只是场地更小。','A higher ticket price does not necessarily mean the concert costs more to produce / the venue may simply be smaller.','not necessarily 表示某事未必成立，不代表绝不成立。','句子提醒票价与制作成本之间没有必然关系。'),M('A higher ticket price necessarily means production costs rose, even though the venue became much smaller and costs fell.','A higher ticket price does not necessarily mean production costs rose; other factors may explain it.','not necessarily 否认必然推论，而非断定价格和成本必然同向。','distinction'),[q('Does a higher ticket price prove production costs rose?','no, it does not necessarily prove that','yes, it always proves that','only if the concert has a necktie','not necessarily 表示不能必然推出制作成本上涨。'),q('What alternative explanation does the sentence give?','the venue may be smaller','the band became a nebula','the tickets were all free','场地规模可能解释票价差异。',1),q('Not necessarily means?','not inevitably or not in every case','certainly and without exception','never at any time','该短语表示未必如此。',1,'distinction'),q('Necessarily is formed from necessary plus?','-ly','-ness','-able','副词 necessarily 由 necessary 加 -ly 构成。',1,'word-formation')]);
P('necessary','Necessary came through Old French necessaire from Latin necessarius, “unavoidable or needed”; it can mean essential, inevitable, or (usually plural) basic provisions.',[C('necessary.s1','必需条件','A waterproof coat is necessary for the survey because the team will work outside during the rainy season.','调查期间团队要在雨季户外工作，因此防水外套是必需的。','A waterproof coat is necessary for the survey / because the team will work outside / during the rainy season.','necessary 表示为实现目的所必需的。','雨季户外调查需要防水衣物。'),C('necessary.s2','逻辑必然','If every entrance is locked and no key is available, it is necessary that the caretaker wait for the locksmith.','如果所有入口都锁着且没有钥匙，管理员就必然得等锁匠来。','If every entrance is locked and no key is available / it is necessary that the caretaker wait for the locksmith.','necessary 可表示在某个条件成立后不可避免的结果。','没有入口钥匙时只能等锁匠开门。'),C('necessary.s3','必需品','The relief workers packed blankets, water, and other necessaries before travelling to the isolated village.','救援人员出发去偏远村庄前，装好了毛毯、水和其他必需品。','The relief workers packed blankets, water, and other necessaries / before travelling / to the isolated village.','the necessaries 常用复数名词，表示生活或工作必需品。','毛毯和水是救援行动需要带上的用品。')],M('A waterproof coat was necessary for the rainy-season survey, so the team deliberately left every coat behind.','The team packed waterproof coats because they were necessary for working outside in the rainy season.','如果防水衣物是必需的却全部不带，行动安排就自相矛盾。','meaning'),[q('Why was a waterproof coat necessary?','the survey was outdoors in the rainy season','the team stayed in a dry office','the village had a neat library','雨季户外调查需要防水外套。',1),q('What must the caretaker do if there is no key?','wait for the locksmith','walk through a locked door','travel to a nebula','所有入口锁闭且无钥匙时只能等锁匠。',2),q('What does necessaries mean in the relief example?','basic items needed for the trip','people who repair locks','all possible luxuries','复数 necessaries 指必需品。',3,'distinction'),q('Which meaning appears in necessary that the caretaker wait?','unavoidable under the stated conditions','tidy and orderly','unmixed with water','既定条件使等待成为不可避免的结果。',2,'distinction')]);
P('necessitate','Necessitate is based on Latin necessitas (“need, necessity”) and means to make something necessary or force someone to take an action.',[C('necessitate.s1','使成为必要','The cracked support beam necessitated a new safety inspection before workers could enter the warehouse.','支撑梁开裂，因此工人进入仓库前必须重新进行安全检查。','The cracked support beam necessitated a new safety inspection / before workers could enter the warehouse.','necessitate 作及物动词表示某种情况使某事成为必需。','梁柱损坏导致必须先检查。'),C('necessitate.s2','迫使行动','A sudden leak necessitated the residents’ moving upstairs until plumbers repaired the ceiling pipe.','突然漏水迫使居民先搬到楼上，直到水管工修好天花板里的管道。','A sudden leak necessitated the residents’ moving upstairs / until plumbers repaired the ceiling pipe.','necessitate 可表示迫使某人采取必要行动。','漏水迫使住户临时转移。')],M('The cracked beam necessitated workers entering the warehouse without any inspection or safety check.','The cracked beam necessitated a safety inspection before workers entered the warehouse.','necessitate 表示使某事不可避免；危险梁柱需要先检查而不是跳过检查。','meaning'),[q('What did the cracked beam necessitate?','a new safety inspection','a larger monthly bill','a necktie for each worker','梁柱开裂使重新检查成为必需。'),q('Why did residents move upstairs?','a leak forced them to leave the affected area','they wanted to visit a nebula','the plumber asked for a necklace','漏水迫使居民临时搬到楼上。',2),q('Which event would necessitate an evacuation?','a gas leak in the building','a tidy shelf','a nearby shop opening','严重燃气泄漏会使疏散成为必需。',1,'context'),q('Necessitate means?','make necessary or force a response','make neat and orderly','come almost to a point','necessitate 表示导致必须采取行动。',1,'meaning')]);
P('necessity','Necessity comes from Latin necessitas, “need or inevitability”; it names a required condition, an essential item, or an unavoidable force.',[C('necessity.s1','必要性','The necessity of a backup generator became clear when the storm cut power to the hospital overnight.','风暴夜间切断医院电力后，备用发电机的必要性显而易见。','The necessity of a backup generator / became clear / when the storm cut power to the hospital overnight.','necessity 指某事必须存在或必须完成的事实。','停电显示备用电源不可或缺。'),C('necessity.s2','必需品','For the overnight hike, water and a first-aid kit are necessities, while the heavy camera is optional.','夜间徒步时，水和急救包是必需品，沉重的相机则可带可不带。','For the overnight hike / water and a first-aid kit are necessities / while the heavy camera is optional.','necessities 作复数名词指生活或特定活动所需的物品。','水和急救包是徒步必需品。'),C('necessity.s3','不得已','Out of necessity, the residents shared one generator until the repair crew restored power to each block.','出于不得已，居民们共用一台发电机，直到维修队恢复各街区供电。','Out of necessity / the residents shared one generator / until the repair crew restored power to each block.','out of necessity 表示因情况所迫、没有更好选择。','电力未恢复时只能暂时共用发电机。')],M('The hikers packed a heavy camera as a necessity and left their only water and first-aid kit behind.','The hikers packed water and a first-aid kit as necessities and treated the camera as optional.','水和急救包是基本必需品；沉重相机并非同等必需。','distinction'),[q('What made a backup generator necessary?','the storm cut power to the hospital','the hospital received a new necklace','the lights were already working','断电暴露了备用电源的必要性。'),q('Which items are necessities for the hike?','water and a first-aid kit','a heavy camera only','a set of neckties','水和急救包是徒步必需品。',2),q('What does out of necessity imply?','circumstances left no good alternative','the action was chosen purely for fun','the action was almost completed','居民因无更好选择而共用发电机。',3,'distinction'),q('Which noun form means a required condition?','necessity','necessary','necessarily','necessity 是表示必要性这一状态的名词。',1,'word-formation')]);
P('neck','Neck continues Old English hnecca; it names the body part joining head and shoulders and a narrow neck-like part of an object or garment.',[C('neck.s1','身体部位','The physiotherapist asked the cyclist to turn her neck slowly after the long ride, stopping if the movement hurt.','长途骑行后，理疗师让骑手慢慢转动脖子，一旦疼痛就停下。','The physiotherapist asked the cyclist to turn her neck slowly / after the long ride / stopping if the movement hurt.','neck 作名词指连接头部和肩膀的身体部位。','转动脖子用于缓解骑行后的僵硬。'),C('neck.s2','物体狭窄部分','The bottle’s narrow neck made it easier to pour the oil without spilling it on the counter.','瓶身的窄颈让油更容易倒出，也不容易洒在台面上。','The bottle’s narrow neck / made it easier to pour the oil / without spilling it on the counter.','neck 可指瓶子或衣服等物体的狭窄部分。','瓶口下方狭窄部分便于控制液流。')],M('The bottle’s wide base was called its neck, while its narrow opening was called its body.','The bottle’s narrow upper section was called its neck.','neck 在瓶子上指狭窄部分，不是宽阔底座。','distinction'),[q('What did the physiotherapist ask the cyclist to turn?','her neck','the bottle cap','the railway station','理疗师让她慢慢转动脖子。',1),q('Why was the bottle neck useful?','it helped pour oil without spilling','it held a railway ticket','it made the bottle a necklace','瓶颈便于控制倒油。',2),q('Which use is not about a body part?','the neck of a bottle','the cyclist’s neck','a stiff neck after riding','瓶子的狭窄部分是物体义。',1,'distinction'),q('What does the human neck join?','the head and shoulders','the hand and wrist','the foot and ankle','脖子连接头部和肩膀。',1,'meaning')]);
P('necklace','Necklace combines neck and lace, originally a lace or chain worn around the neck; it can also name a decorative neck band.',[C('necklace.s1','项链','She wore a silver necklace over the dark dress, fastening its small clasp behind her neck before the ceremony.','她在深色连衣裙外戴了一条银项链，并在仪式前把小扣子系在颈后。','She wore a silver necklace over the dark dress / fastening its small clasp / behind her neck before the ceremony.','necklace 通常指绕在脖子上佩戴的链条或珠串首饰。','银链和颈后搭扣体现项链用法。'),C('necklace.s2','颈圈状饰物','The museum displayed a decorative shell necklace that formed a broad band around the carved statue’s neck.','博物馆展示了一件装饰性的贝壳颈圈，环绕着雕像的脖子形成宽带。','The museum displayed a decorative shell necklace / that formed a broad band / around the carved statue’s neck.','necklace 也可泛指环绕颈部佩戴的装饰带。','贝壳装饰带绕着雕像颈部。')],M('She fastened the necklace around her ankle and called it jewellery worn around the neck.','She fastened the necklace around her neck as jewellery.','necklace 的佩戴位置是颈部，不是脚踝。','meaning'),[q('What did she fasten behind her neck?','the necklace clasp','a bottle’s narrow neck','a physiotherapy strap','她在颈后扣好项链。'),q('What material formed the museum’s decorative band?','shells','steel wrenches','wetland reeds','颈圈状装饰由贝壳构成。',2),q('A necklace is worn around the?','neck','ankle','waist only','necklace 是佩戴在颈部的饰物。',1,'meaning'),q('Which detail identifies the broader necklace sense?','a shell band around a statue’s neck','a chain clasped behind a person’s neck','a bottle opening used to pour oil','第二例是环绕颈部的装饰带。',2,'distinction')]);
P('necktie','Necktie combines neck and tie and names a narrow piece of cloth tied around the neck, usually with a knot.',C('necktie.s1','领带','The clerk loosened his necktie after the hearing and packed it carefully so it would not crease on the train.','听证会结束后，职员松开领带并仔细收好，免得在火车上压出折痕。','The clerk loosened his necktie after the hearing / and packed it carefully / so it would not crease on the train.','necktie 指围在脖子上打结佩戴的窄布条。','松开并防皱收纳的是领带。'),M('The clerk called a metal chain worn around the wrist a necktie.','The clerk wore a narrow cloth tie knotted around his neck.','手腕金属链既不是布条，也不是颈部服饰。','meaning'),[q('What did the clerk pack carefully?','his necktie','a neatness report','a bottle with a narrow neck','职员收好领带以免起皱。'),q('How is a necktie usually worn?','tied in a knot around the neck','wrapped around the ankle','fastened to a bottle','领带围颈并打结。',1),q('Which item is a necktie?','a narrow cloth strip knotted under a collar','a metal bracelet','a chain of beads worn as a necklace','领带是打结佩戴的窄布条。',1,'distinction'),q('The compound necktie joins neck with?','tie','time','tube','necktie 由 neck 与 tie 组成。',1,'word-formation')]);
P('necrosis','Necrosis comes from Greek nekrosis, “deadness,” from nekroun “to make dead”; it is pathological death of tissue in a living organism.',C('necrosis.s1','组织坏死','The surgeon removed a small area of necrosis from the patient’s foot after circulation had been blocked for too long.','血液循环受阻太久后，外科医生切除了患者足部一小块坏死组织。','The surgeon removed a small area of necrosis from the patient’s foot / after circulation had been blocked / for too long.','necrosis 是生物仍存活时局部组织的病理性死亡。','循环阻断导致局部组织坏死。'),M('The report called healthy, fully functioning tissue necrosis even though the cells remained alive and undamaged.','The report identified necrosis where tissue had died after its blood supply was blocked.','活着且功能正常的组织不属于坏死。','meaning'),[q('What contributed to the patient’s necrosis?','blood circulation was blocked too long','the patient wore a necktie','a nearby clinic closed','血流受阻导致局部组织死亡。'),q('Necrosis means?','pathological death of tissue','a necklace worn around the neck','a cloud of gas in space','necrosis 指病理性组织坏死。',1),q('What distinguishes necrosis from the death of an entire organism?','it is local tissue death while the organism remains alive','it means the whole person has died','it is a normal tissue colour','necrosis 是活体局部组织死亡。',1,'distinction'),q('The Greek element nekros is associated with?','death','closeness','tidiness','necrosis 来源中的希腊语词根与死亡有关。',1,'word-formation')]);
P('nectar','Nectar comes from Greek nektar, the divine drink of the gods in Greek myth; it is the sweet liquid produced by flowers and collected by bees.',C('nectar.s1','花蜜','A bee moved between the lavender flowers, gathering nectar before returning to the hive at the edge of the garden.','一只蜜蜂在薰衣草花间穿梭采集花蜜，然后飞回花园边缘的蜂巢。','A bee moved between the lavender flowers / gathering nectar / before returning to the hive / at the edge of the garden.','nectar 指花朵分泌、供昆虫采集的甜液。','蜜蜂从花朵采集甜液带回蜂巢。'),M('The beekeeper said the bee collected nectar from a dry stone wall where no flowers or sweet liquid existed.','The beekeeper said the bee collected nectar from flowering lavender.','石墙没有花朵，也不会分泌花蜜。','meaning'),[q('What did the bee gather from lavender?','sweet flower liquid','a necktie','mortar dust','蜜蜂采集薰衣草的花蜜。'),q('Where did the bee return after collecting nectar?','the hive at the garden’s edge','a nearby clinic','a river station','采蜜后蜜蜂飞回花园边缘的蜂巢。',1),q('Nectar is produced by?','flowers','stone walls','moth larvae','花蜜由花朵产生。',1,'meaning'),q('What was nectar in Greek myth?','the gods’ drink','a kind of flower','the name for a bee’s hive','其词源指希腊神话中诸神饮品。',1,'word-formation')]);
P('nectarine','Nectarine came through French for a smooth-skinned peach; its name may be associated with nectar for sweetness, though that link is uncertain.',C('nectarine.s1','水果外观','At the market, she chose a ripe nectarine with smooth red skin instead of the fuzzy peaches beside it.','在市场上，她挑了一只红皮光滑的熟油桃，而没有选旁边带绒毛的桃子。','At the market / she chose a ripe nectarine with smooth red skin / instead of the fuzzy peaches beside it.','nectarine 是表皮光滑的桃类水果。','光滑果皮把油桃与绒毛桃区分开。'),M('The shopper chose a nectarine because its skin was densely covered with peach fuzz.','The shopper chose a nectarine because its skin was smooth.','油桃的典型区别是表皮光滑，而非有绒毛。','distinction'),[q('How did the nectarine’s skin look?','smooth and red','covered with thick fuzz','like a metal surface','例句说油桃表皮红且光滑。'),q('What fruit sat beside the nectarine?','fuzzy peaches','nectar from lavender','a bowl of mortar','市场上油桃旁边是带绒毛的桃子。',1),q('Which fruit is a nectarine?','a smooth-skinned kind of peach','a fuzzy peach with no stone','a flower’s sweet liquid','油桃是表皮光滑的桃类。',1,'meaning'),q('Why is the nectar link in the name stated cautiously?','the sweetness association is uncertain','nectarine means “bee” in Old English','the fruit is made by bees','名字与 nectar 的联系并不确定。',1,'word-formation')]);
P('need','Need continues Old English nēodian/nēd and can be a verb meaning require, a modal for lack of obligation in questions or negatives, a noun for a requirement, or a state of poverty.',[C('need.s1','需要某物','The seedlings need steady warmth for the first week, so the gardener moved them into a sheltered greenhouse.','幼苗第一周需要稳定的温度，因此园丁把它们移进有遮蔽的温室。','The seedlings need steady warmth / for the first week / so the gardener moved them into a sheltered greenhouse.','need 作动词表示因重要或必要而需要某物。','温度是幼苗生长所需条件。'),C('need.s2','不必（情态）','Need you print the whole report? The office can accept a signed digital copy instead.','你一定要把整份报告打印出来吗？办公室也接受签署过的电子版。','Need you print the whole report? / The office can accept a signed digital copy instead.','need 在疑问句中作情态动词，可询问某事是否有必要。','替代方案表明打印并非必须。'),C('need.s3','必要条件','There is a real need for clear labels in the archive because several boxes contain fragile documents.','档案室确实需要清楚的标签，因为有几个箱子装着易损文件。','There is a real need for clear labels in the archive / because several boxes / contain fragile documents.','need 作名词指必须做某事或必须存在某物的情况。','易损档案使清晰标签成为必要。'),C('need.s4','贫困困窘','The charity delivered food to families living in need after the factory closure removed their only source of income.','工厂关闭使一些家庭失去唯一收入来源后，慈善机构向陷入贫困的家庭送去食物。','The charity delivered food to families living in need / after the factory closure / removed their only source of income.','in need 指缺少基本生活资源、处于贫困或困窘状态。','失业后家庭缺乏食物和收入。')],M('Need you print the report? means that printing is compulsory and no digital copy can be accepted.','Need you print the report? asks whether printing is necessary; here a signed digital copy is acceptable.','疑问句中的情态 need 询问必要性，不表示强制必须。','grammar'),[q('Why were the seedlings moved into a greenhouse?','they needed steady warmth','they were already mature trees','the market had no peaches','幼苗需要稳定温度。',1),q('Does the office require the whole report on paper?','no, a signed digital copy is accepted','yes, it rejects all digital files','only if it contains nectar','办公室接受签署过的电子版。',2,'grammar'),q('What does There is a need for labels mean?','clear labels are necessary','the labels are poor and unemployed','the labels are almost finished','名词 need 表示标签有必要。',3,'distinction'),q('Which families are living in need?','families without enough resources after losing income','families whose seedlings need warmth','families with every basic resource','in need 指处于贫困困窘中。',4,'meaning')]);
P('need to','Need to is need plus the infinitive marker to and expresses that an action is necessary or required.',C('need to.s1','必要行动','You need to save the signed receipt because the finance office will not reimburse the travel claim without it.','你需要保存签字收据，因为没有它财务处不会报销差旅费。','You need to save the signed receipt / because the finance office / will not reimburse the travel claim without it.','need to + 动词原形表示有必要或有要求去做某事。','报销要求使保存收据成为必要行动。'),M('The traveller needs to submit the receipt but throws it away before filing the reimbursement claim.','The traveller needs to keep and submit the signed receipt to claim reimbursement.','若要报销就必须保留收据；丢掉它会妨碍完成必要步骤。','meaning'),[q('What must the traveller keep?','the signed receipt','a fuzzy nectarine','a bottle’s neck','报销需要签字收据。'),q('Why is the receipt needed?','the finance office requires it for reimbursement','it makes the train arrive earlier','it is a flower’s nectar','财务处规定报销差旅费要收据。',1),q('Which sentence correctly uses need to?','We need to lock the archive before leaving.','We need locking to the archive before leaving.','We need to locked the archive before leaving.','need to 后接动词原形 lock。',1,'grammar'),q('Need to expresses?','that an action is necessary','that an action is nearly complete','that someone is a neighbour','need to 表示有必要采取行动。',1,'meaning')]);
P('needed','Needed is the past tense and past participle of need; it is also an adjective meaning required or necessary.',[C('needed.s1','过去需要','During the blackout, the clinic needed extra batteries for its emergency monitors, but power returned before delivery.','停电期间诊所需要额外电池供急救监护仪使用，不过电池送达前供电就恢复了。','During the blackout / the clinic needed extra batteries / for its emergency monitors / but power returned before delivery.','needed 可作 need 的过去式，说明过去存在需要。','停电时诊所曾需要电池。'),C('needed.s1','必需的','Only the needed documents were placed on the desk; the rest stayed locked in the archive cabinet.','桌上只放了必需的文件，其余文件仍锁在档案柜里。','Only the needed documents were placed on the desk / the rest stayed locked / in the archive cabinet.','needed 也可作形容词，修饰所需或必需的事物。','桌上挑出的文件是办理事务所需的。')],M('The clinic needed extra batteries yesterday, meaning it will need them at every future moment as well.','The clinic needed extra batteries during yesterday’s blackout.','过去式 needed 表示过去需要，不自动延伸到未来所有时刻。','verb-form'),[q('What did the clinic need during the blackout?','extra batteries','smooth-skinned peaches','a necktie','监护仪在停电时需要额外电池。'),q('Where were the needed documents placed?','on the desk','inside the clinic monitor','on a flower','必需文件被放在桌上。',1),q('In The clinic needed batteries, needed is?','the past tense of need','a future tense','a plural noun','needed 说明过去曾经需要。',1,'grammar'),q('In the needed documents, needed means?','required','unnecessary','almost complete','此处 needed 作形容词，意为必需的。',1,'distinction')]);
P('needle','Needle continues Old English nǣdl; it can be a sewing or injection tool, a pointer or pine leaf, or a verb meaning to provoke someone repeatedly.',[C('needle.s1','缝纫针','The tailor threaded a fine needle and repaired the torn cuff before returning the jacket to its owner.','裁缝穿好细针，在把夹克还给主人前补好了撕裂的袖口。','The tailor threaded a fine needle / and repaired the torn cuff / before returning the jacket to its owner.','needle 可指带孔、用来穿线缝纫的细尖钢针。','穿线后缝补袖口的是缝纫针。'),C('needle.s2','仪表指针','The pressure needle rose into the red zone, warning the operator to shut down the boiler immediately.','压力表指针升入红色区域，警告操作员立即关闭锅炉。','The pressure needle rose into the red zone / warning the operator / to shut down the boiler immediately.','needle 也可指仪表上的细长指针或松树针叶。','表针移动到危险刻度。'),C('needle.s3','故意刺激','His teammates kept needling him about the missed goal until the coach told them to stop.','队友不断拿他错失进球的事刺激他，直到教练让大家停下。','His teammates kept needling him about the missed goal / until the coach told them to stop.','needle 作动词表示反复挖苦、刺激或惹恼某人。','反复取笑错失进球让他烦躁。')],M('The tailor threaded the pressure needle through cloth to repair the cuff.','The tailor used a sewing needle threaded with cotton to repair the cuff.','压力表指针不能用于缝纫；缝纫针穿线缝布。','confusable'),[q('What tool repaired the torn cuff?','a threaded sewing needle','the pressure gauge pointer','a pine leaf','裁缝用穿线针缝补袖口。'),q('What did the pressure needle signal?','pressure had entered the red zone','the jacket needed sewing','the players had scored','指针进入红区意味着压力过高。',2),q('What did teammates do by needling him?','repeatedly teased him about the missed goal','sewed his jacket cuff','measured the boiler pressure','needle 作动词表示反复刺激、取笑。',3,'distinction'),q('Which needle is not a physical tool?','teammates needling a player','a tailor threading a sewing needle','a gauge needle entering the red zone','needling someone 是比喻性动词用法。',3,'distinction')]);
P('needlefish','Needlefish combines needle and fish and names a slender fish whose long jaws form a sharp, needle-like bill.',C('needlefish.s1','鱼类形态','The needlefish skimmed just below the surface, its long pointed jaws flashing as it chased small fish in the bay.','颌针鱼贴着水面游动，追逐海湾里的小鱼时，细长尖嘴闪着光。','The needlefish skimmed just below the surface / its long pointed jaws flashing / as it chased small fish in the bay.','needlefish 是体形细长、上下颌延伸成尖喙的鱼。','细长尖嘴使它容易辨认。'),M('The guide identified a round-bodied carp with a blunt mouth as a needlefish because it had no long jaws.','The guide identified the slim fish with long pointed jaws as a needlefish.','针鱼的特征正是细长体形和针状长颌。','distinction'),[q('How did the needlefish move in the bay?','just below the surface','through dry grass','along a mountain ridge','鱼贴近水面游动。'),q('What feature gives the fish its name?','long pointed jaws like a needle','a smooth peach-like skin','a necklace of scales','长而尖的颌部像针。',1),q('Which fish is a needlefish?','a slim fish with a long pointed bill','a round fish with a blunt mouth','a fish with no jaws','针鱼有细长尖嘴。',1,'context'),q('Needlefish combines needle with?','fish','moth','neck','needlefish 是 needle 与 fish 的复合词。',1,'word-formation')]);
P('needlelike','Needlelike combines needle and -like and means long, slender, and sharp in the form of a needle.',C('needlelike.s1','细长尖锐','The cactus had needlelike spines that pierced the gardener’s glove when she moved the pot.','仙人掌长着针状刺，园丁挪动花盆时刺穿了她的手套。','The cactus had needlelike spines / that pierced the gardener’s glove / when she moved the pot.','needlelike 作形容词，描述细长、尖锐而像针的形状。','刺能刺穿手套，体现细尖形状。'),M('The botanist described a broad, blunt leaf as needlelike even though it had no narrow or pointed shape.','The botanist described the cactus’s long, sharp spines as needlelike.','宽而钝的叶片不具备针状的细长尖锐形态。','meaning'),[q('What pierced the gardener’s glove?','the cactus’s sharp spines','a nectarine’s smooth skin','a necklace clasp','仙人掌尖刺刺穿了手套。'),q('Needlelike describes something that is?','long, slender, and sharp','wide, blunt, and flat','soft and round','needlelike 指细长尖锐、像针一样。',1),q('Which object is needlelike?','a thin pointed cactus spine','a broad rounded leaf','a wide bowl','细长尖刺具有针状形态。',1,'context'),q('The suffix -like means?','having the form or qualities of','without any','made entirely from','-like 表示“像……一样”。',1,'word-formation')]);
P('needless','Needless is need plus -less and means unnecessary or serving no useful purpose.',C('needless.s1','不必要','The team avoided needless travel by sending the signed forms electronically instead of driving to the office.','团队通过电子方式发送签字表格，避免了不必要的驾车往返。','The team avoided needless travel / by sending the signed forms electronically / instead of driving to the office.','needless 表示没有必要、不会带来有用结果。','电子提交已足够，开车前往属于多余行程。'),M('The manager called the required safety inspection needless even though the law made it compulsory before reopening.','The manager called an extra duplicate inspection needless because the required safety check had already passed.','法律规定的强制检查是必要的；重复且无额外用途的检查才可称 needless。','distinction'),[q('How did the team avoid needless travel?','they sent signed forms electronically','they drove to the office twice','they left the forms unsigned','电子提交免去往返办公室。'),q('Needless travel is travel that?','is not necessary','must happen by law','is almost finished','needless 意为不必要的。',1),q('Which cost is needless?','a second identical test after the required test passed','the only legal safety check','a necessary trip to hospital','重复而无新用途的测试是不必要的。',1,'context'),q('Needless is formed from need plus?','-less','-ful','-en','-less 表示缺少需要或必要性。',1,'word-formation')]);
P('needlework','Needlework combines needle and work and means hand sewing, embroidery, or related decorative stitching.',C('needlework.s1','手工缝绣','Her grandmother taught her needlework by showing how to embroider a small blue flower onto a linen napkin.','祖母教她做针线活，示范如何在亚麻餐巾上绣一朵蓝色小花。','Her grandmother taught her needlework / by showing how to embroider / a small blue flower onto a linen napkin.','needlework 泛指手工缝纫、刺绣等针线技艺。','用针线在布上绣花属于 needlework。'),M('The student described operating an industrial crane as needlework, although no sewing or stitching was involved.','The student described hand embroidery on the napkin as needlework.','操作起重机与用针线缝绣无关。','meaning'),[q('What design did she embroider?','a small blue flower','a pressure gauge','a motor race','餐巾上绣了一朵蓝色小花。'),q('What does needlework include?','hand sewing and embroidery','crane operation','measuring blood pressure','needlework 指手工缝纫或刺绣。',1),q('Which activity is needlework?','stitching a pattern into cloth by hand','repairing a boiler gauge','driving a delivery van','手工在布料上缝出图案是针线活。',1,'context'),q('The compound needlework combines needle and?','work','water','wood','needlework 由 needle 与 work 组成。',1,'word-formation')]);
P('needs','Needs is the plural noun from need and refers to things or conditions someone must have.',C('needs.s1','必需条件','The shelter assessed each family’s needs before distributing blankets, medicine, and child-sized shoes.','避难所先评估每个家庭的需求，再分发毛毯、药品和儿童尺码的鞋。','The shelter assessed each family’s needs / before distributing blankets, medicine, / and child-sized shoes.','needs 指为生活或完成任务必须具备的事物或条件。','分发物资前先核实各家庭缺少什么。'),M('The coordinator ignored the families’ needs and distributed only decorative items they did not require.','The coordinator assessed families’ needs and provided essential blankets, medicine, and shoes.','只发放无用装饰品没有回应必需需求。','meaning'),[q('What did the shelter assess?','what each family required','how many neckties the staff owned','the distance to the nearest station','避难所先评估各家庭的需求。'),q('Which items were distributed?','blankets, medicine, and child-sized shoes','whisky and glass necklaces','cactus spines','避难所发放基本物资。',1),q('Needs most nearly means?','required things or conditions','unnecessary decorations','the past tense of need','needs 指必须具备的东西或条件。',1,'meaning'),q('Why assess needs before distributing supplies?','to match essential items to each family','to avoid helping anyone','to measure the staff’s neatness','先核实需求才能提供合适的必需品。',1,'context')]);
P('needy','Needy is need plus -y and describes people who are poor and require help or support.',C('needy.s1','贫困需助','The community kitchen serves needy families who cannot afford a reliable meal every day.','社区食堂为无力每天负担稳定膳食的贫困家庭提供餐食。','The community kitchen serves needy families / who cannot afford / a reliable meal every day.','needy 形容缺少钱或基本资源、需要援助的人。','家庭无力负担日常食物，符合贫困需助义。'),M('The charity reserved food for wealthy households that had more than enough supplies and described them as needy.','The charity reserved food for needy households that lacked reliable meals.','拥有充足资源的家庭并非此处所说的贫困需助者。','meaning'),[q('Who receives meals from the community kitchen?','families unable to afford food reliably','families with a full private pantry','the nearby clinic’s staff only','食堂服务无力稳定负担食物的家庭。'),q('A needy person is?','poor and in need of help','tidy and orderly','almost finished','needy 指贫困并需要帮助的。',1),q('Which family is most clearly needy?','one that cannot afford daily meals','one that owns several full pantries','one that volunteers to deliver food','无力负担日常膳食说明家庭需要援助。',1,'context'),q('Needy is formed from need plus?','-y','-less','-ment','needy 由 need 加 -y 构成形容词。',1,'word-formation')]);
P('negate','Negate comes from Latin negare, “to deny”; it can deny that something is true or cancel its effect.',[C('negate.s1','否定主张','The witness’s signed statement did not negate the video evidence, which clearly showed the car entering the yard.','证人的签字陈述并未否定录像证据，录像清楚显示汽车驶入院子。','The witness’s signed statement did not negate the video evidence / which clearly showed / the car entering the yard.','negate 可表示否认或使某证据不再成立。','陈述没有推翻录像所显示的事实。'),C('negate.s2','抵消作用','A small solar panel cannot fully negate the building’s high energy use, but it reduces the daytime electricity demand.','小型太阳能板不能完全抵消大楼的高能耗，但能降低白天的用电需求。','A small solar panel cannot fully negate the building’s high energy use / but it reduces / the daytime electricity demand.','negate 也可表示取消或抵消某种效果。','太阳能部分降低能源需求，却不能完全抵消高耗能。')],M('The witness’s denial negated the video evidence even though the footage still plainly showed the car entering.','The witness’s denial did not negate the video evidence, which continued to show the car entering.','与清晰录像相矛盾的口头否认没有使录像证据失效。','meaning'),[q('What did the video show?','the car entering the yard','the witness building a solar panel','a flower collecting nectar','录像清楚显示汽车驶入院子。',1),q('What effect did the panel have on energy use?','it reduced daytime demand but did not eliminate high use','it erased every electricity need','it increased the building’s demand','太阳能板降低需求但没有完全抵消高能耗。',2),q('Which sense of negate appears in “negate the evidence”?','deny or nullify a claim','make a room tidy','need something','negate 可否定主张或使其不成立。',1,'distinction'),q('Which sentence uses negate as “cancel an effect”?','The medicine negated some of the toxin’s effects.','She negated the claim that the bridge was closed.','The witness negated the recording by denying it.','药物抵消毒素影响属于效果义。',2,'distinction')]);
P('negation','Negation comes from Latin negatio, from negare (“deny”); it is a denial or a grammatical/logical form expressing that something is not the case.',C('negation.s1','逻辑与语法否定','In “The door is not open,” the word not marks negation and changes the statement from an open door to a closed one.','在“The door is not open”中，not 表示否定，把“门开着”的陈述改为“门没开”。','In “The door is not open,” / the word not marks negation / and changes the statement / from an open door to a closed one.','negation 指否认某事成立的逻辑或语法形式。','not 是句中否定词。'),M('The logician called “The door is open” a negation even though the sentence affirms that it is open.','The logician called “The door is not open” a negation because it denies the affirmative statement.','肯定句没有否定成分，不是对命题的否认。','grammar'),[q('Which word marks negation in the sentence?','not','door','open','not 把肯定命题转为否定。',1),q('What does the sentence “The door is not open” deny?','that the door is open','that a witness signed a statement','that a panel uses solar energy','句子否认门处于打开状态。'),q('Which sentence contains grammatical negation?','The clinic did not close.','The clinic closes at noon.','The clinic has a nearby door.','did not 构成语法否定。',1,'grammar'),q('Negation is related to the verb?','negate','neaten','need','negation 与 negate 同源。',1,'word-formation')]);
P('negative','Negative came through Old French negatif from Latin negativus, from negare (“deny”); it can express refusal or an unfavourable, pessimistic view.',C('negative.s1','否定或消极','The review was negative about the repair plan, arguing that the new beam would not solve the water leak.','这篇评论对维修方案持否定态度，认为新横梁无法解决漏水。','The review was negative about the repair plan / arguing that the new beam / would not solve the water leak.','negative 可表示否定、不赞成，也可表示坏的或缺乏希望的。','评论指出方案无法解决核心问题。'),M('The review was negative and strongly supported the repair plan as certain to stop the leak.','The review was negative because it argued the plan would not stop the leak.','强烈支持方案并看好成功，不能称为对此方案持否定态度。','meaning'),[q('What did the review think of the repair plan?','it would not solve the leak','it would certainly fix every problem','it was a type of necklace','评论认为新横梁解决不了漏水。'),q('A negative review is generally?','unfavourable','certainly approving','a grammatical plural','negative 可指不利或不赞成的评价。',1),q('Which response is negative about a proposal?','“This will not fix the leak.”','“This will solve the leak.”','“The meeting starts at noon.”','明确指出方案不能解决问题，表达否定态度。',1,'context'),q('Negative is historically connected to Latin for?','deny','shine','need','其词源与拉丁语“否认”有关。',1,'word-formation')]);
P('negativity','Negativity is negative plus -ity and means a tendency to focus on problems or the bad side of situations.',C('negativity.s1','消极倾向','The manager challenged the team’s negativity by asking them to list one workable solution for every problem they raised.','经理要求团队每提出一个问题，就列出一个可行方案，以纠正他们的消极倾向。','The manager challenged the team’s negativity / by asking them to list one workable solution / for every problem they raised.','negativity 指习惯关注坏处、问题或失败可能性的倾向。','团队只列问题，经理要求同时提出方案。'),M('The team showed negativity by calmly weighing risks and benefits and noting several possible solutions.','The team showed negativity by dismissing every proposal and focusing only on what might fail.','客观分析优缺点并提出方案不是只关注坏处的消极倾向。','distinction'),[q('How did the manager respond to negativity?','asked for a workable solution to each problem','asked the team to stop working','removed all project goals','经理要求每个问题配一个可行方案。'),q('Negativity is a tendency to focus on?','the bad side or possible failure','every available benefit only','nearby locations','negativity 指关注问题或坏处。',1),q('Which behaviour shows negativity?','rejecting every idea by listing only what could go wrong','weighing risks and benefits fairly','offering a practical repair','只列失败可能并否定一切建议属于消极倾向。',1,'context'),q('Negativity is formed from negative plus?','-ity','-ly','-en','-ity 构成抽象名词 negativity。',1,'word-formation')]);
P('neglect','Neglect came through Old French from Latin neglegere, “to disregard”; it means to fail to care for someone, fail to do a duty, or the state of receiving too little care.',[C('neglect.s1','疏于照顾','The landlord neglected the leaking roof for months, and rain eventually damaged the tenants’ bedrooms.','房东几个月来一直不管漏水的屋顶，雨水最终损坏了租客的卧室。','The landlord neglected the leaking roof for months / and rain eventually damaged / the tenants’ bedrooms.','neglect 可指未妥善照料某人或某物。','屋顶长期无人维修，造成室内损坏。'),C('neglect.s2','漏做职责','She neglected to renew the safety certificate, so the workshop had to close until the paperwork was approved.','她忘了续办安全证书，因此车间只能关闭，直到文件获批。','She neglected to renew the safety certificate / so the workshop had to close / until the paperwork was approved.','neglect to do 表示疏忽而没有完成应做的事。','未续证使工作间不得不暂时关闭。'),C('neglect.s3','无人照管状态','Years of neglect left the playground’s swings rusty and its safety surface cracked.','多年无人维护使游乐场秋千生锈，安全地面也开裂。','Years of neglect left the playground’s swings rusty / and its safety surface cracked.','neglect 作名词指没有给予所需照料的状态。','设施破损显示多年缺少维护。')],M('The landlord neglected the roof by repairing every leak as soon as it appeared and preventing any damage.','The landlord neglected the roof by leaving its leaks unrepaired for months.','及时维修表示尽到照料，不是疏忽不管。','meaning'),[q('What did the landlord fail to care for?','the leaking roof','the tenants’ necklaces','the workshop’s nectar','屋顶漏水数月未修。'),q('Why did the workshop close?','the safety certificate was not renewed','the landlord repaired the roof','a needlefish entered the room','疏忽续证导致车间暂停营业。',2),q('What did years of neglect do to the playground?','left its equipment rusty and cracked','kept it perfectly maintained','turned it into a nebula','多年缺少维护造成设施损坏。',3,'context'),q('Which use is a noun rather than a verb?','Years of neglect damaged the swings.','The owner neglected the roof.','She neglected to renew the certificate.','第一句 neglect 作名词，指缺少照料的状态。',3,'grammar')]);
P('neglectful','Neglectful combines neglect and -ful and describes someone who fails to give proper attention or care.',C('neglectful.s1','疏于照顾','The report found the caretaker neglectful because she repeatedly left the building’s fire doors propped open.','报告认定看护人疏于职守，因为她一再把建筑物的防火门支开。','The report found the caretaker neglectful / because she repeatedly left / the building’s fire doors propped open.','neglectful 形容没有尽到应有注意或照料的人。','反复违反消防安全要求体现疏忽。'),M('The caretaker was neglectful even though she checked every fire door hourly and repaired each fault immediately.','The caretaker was neglectful because she repeatedly left fire doors open and ignored faults.','及时检查并修复问题与疏忽大意相反。','meaning'),[q('What did the caretaker repeatedly leave open?','the fire doors','the nearby clinic','the nectar bottles','报告指出防火门一再被支开。'),q('Why was the caretaker called neglectful?','she failed to give proper attention to fire safety','she was almost finished with a report','she wore a neat necktie','她未妥善注意消防门的安全。',1),q('Which worker is neglectful?','one who ignores repeated safety faults','one who checks doors and repairs faults promptly','one who asks for a necessary inspection','无视反复出现的安全问题属于疏忽。',1,'context'),q('Neglectful is formed from neglect plus?','-ful','-ness','-er','-ful 构成表示“充满/具有”的形容词。',1,'word-formation')]);
P('negligence','Negligence came through French from Latin neglegentia, “carelessness”; it is failure to take proper care or perform a duty.',C('negligence.s1','过失责任','The investigation attributed the damaged archive boxes to negligence because staff had ignored a known roof leak.','调查把档案箱受损归因于疏忽，因为工作人员无视已知的屋顶漏水问题。','The investigation attributed the damaged archive boxes to negligence / because staff had ignored / a known roof leak.','negligence 指没有采取应有谨慎或没有履行职责。','已知漏水却不处理造成档案受损。'),M('The auditor called the staff’s repeated inspections and prompt roof repairs negligence.','The auditor called the staff’s failure to act on the known leak negligence.','及时检查和维修是尽责行为，不是过失。','meaning'),[q('What damaged the archive boxes?','staff ignored a known roof leak','the boxes were stored neatly','the shelves were made from nectar','已知漏水未处理导致档案箱受损。'),q('Negligence is a failure to?','take proper care or perform a duty','keep a necklace around the neck','come close to a place','negligence 指未尽应有注意或职责。',1),q('Which example could support a negligence claim?','a caretaker ignores a known dangerous leak and property is damaged','a caretaker checks the roof and fixes the leak','a visitor buys a nectarine','无视已知危险并造成损害可能构成过失。',1,'context'),q('Negligence is a noun related to?','neglect','negative','neatly','negligence 与 neglect 表示疏忽的词族相关。',1,'word-formation')]);
P('negligent','Negligent came from Latin neglegent-, “disregarding”; it describes careless failure to perform a duty and, legally, failure of a duty of care that may cause harm.',[C('negligent.s1','一般疏忽','The negligent technician left the freezer door open overnight, spoiling the laboratory samples stored inside.','粗心的技术员整夜没关冰柜门，使里面的实验样本变质。','The negligent technician left the freezer door open overnight / spoiling the laboratory samples / stored inside.','negligent 可泛指没有给予应有注意的粗心行为。','忘关冰柜门造成样本损坏。'),C('negligent.s2','法律过失','The court found the contractor negligent after evidence showed he ignored a required safety barrier and a visitor was injured.','证据显示承包商无视规定的安全护栏并导致访客受伤后，法院认定其构成过失。','The court found the contractor negligent / after evidence showed he ignored a required safety barrier / and a visitor was injured.','法律语境的 negligent 指未尽注意义务并可能因此造成损害。','违反安全要求与受伤后果形成因果关联。')],M('The contractor was legally negligent even though he installed every required barrier and no one was exposed to danger.','The contractor was found negligent because he ignored the required barrier and a visitor was injured.','履行安全义务且无人受危不支持此处的过失认定。','usage'),[q('What did the technician leave open?','the laboratory freezer','the archive door','a necklace clasp','冰柜门整夜没关。'),q('Why did the court find the contractor negligent?','he ignored a required barrier and someone was injured','he installed every barrier correctly','the visitor wore a necktie','无视护栏要求并导致伤害构成法律过失。',2,'usage'),q('Which use is specifically legal?','the court found the contractor negligent','the technician was negligent with the freezer','a student was negligent about neatness','法院认定与法律注意义务相关。',2,'distinction'),q('Negligent means?','not showing enough care in a duty','almost all items','a simple clever solution','negligent 指履职时未尽应有注意。',1,'meaning')]);
P('negligible','Negligible came through French from Latin negliger(e), “to disregard”; it describes an amount or effect too small to merit attention.',[C('negligible.s1','数值极小','The sensor’s error was negligible compared with the storm’s pressure changes, so it did not alter the warning level.','与风暴气压变化相比，传感器误差微不足道，没有改变警报等级。','The sensor’s error was negligible / compared with the storm’s pressure changes / so it did not alter the warning level.','negligible 表示小到不值得考虑或影响很小。','误差没有改变最终警报等级。'),C('negligible.s2','影响极小','The new coating had a negligible effect on the colour of the stone but greatly reduced water damage.','新涂层对石头颜色几乎没有影响，却大幅减少了水损。','The new coating had a negligible effect on the colour of the stone / but greatly reduced / water damage.','negligible effect 指影响小到不会实质改变结果。','涂层基本不改变颜色，但显著影响防水效果。')],M('The sensor error was negligible and shifted the warning by twenty degrees, changing the entire safety decision.','The sensor error was negligible because it was too small to change the warning level.','足以改变安全决策的大误差不能称为微不足道。','measurement'),[q('Did the sensor error change the warning level?','no, it was too small to do so','yes, it shifted the level dramatically','it changed the colour of the stone','例句说明误差没有改变警报等级。'),q('What did the coating barely affect?','the stone’s colour','water damage, which it greatly reduced','the storm pressure','它对颜色影响很小。',2),q('Which amount is negligible?','a difference too small to change a result','a change that reverses the whole decision','a large storm-pressure shift','negligible 指小到不值得计较或影响结果。',1,'measurement'),q('What does negligible effect mean?','an effect too slight to matter','an effect that changes everything','an effect that is impossible to measure in principle','影响微乎其微，实质结果不变。',2,'distinction')]);
P('negligibly','Negligibly is negligible plus -ly and means to a degree so small that it does not materially matter.',C('negligibly.s1','程度极微','The repaired valve leaked negligibly during the first test, but engineers still scheduled a second pressure check.','修好的阀门在首次测试中只有极轻微的泄漏，但工程师仍安排了第二次压力检查。','The repaired valve leaked negligibly during the first test / but engineers still scheduled / a second pressure check.','negligibly 修饰 leaked，表示泄漏量微小到几乎不重要。','泄漏虽轻微，仍需复测确认安全。'),M('The valve leaked negligibly, releasing most of the tank’s contents in a few minutes.','The valve leaked negligibly, releasing only a tiny trace during the test.','几分钟泄出大部分液体是严重泄漏，不是微量泄漏。','measurement'),[q('How much did the repaired valve leak?','only a tiny amount','most of the tank','exactly one full tank','negligibly 表示泄漏量极小。',1,'measurement'),q('What did engineers schedule despite the small leak?','a second pressure check','a motor race','a monthly dance','工程师仍安排第二次压力检查。'),q('Which change is negligibly small?','the reading shifts by 0.001 on a scale where whole units matter','the reading doubles','the valve releases the entire tank','在以整单位判断的尺度上微小偏差几乎不影响结论。',1,'context'),q('Negligibly is the adverb related to?','negligible','negligence','negotiate','negligibly 由 negligible 加 -ly 构成。',1,'word-formation')]);
P('negotiable','Negotiable is negotiate plus -able and means open to discussion and change; of a financial instrument or route, it can mean transferable or passable.',[C('negotiable.s1','条件可商议','The seller said the delivery date was negotiable, so both sides agreed on a later week that suited the factory.','卖家说交货日期可以商量，因此双方同意改到更适合工厂的下一个星期。','The seller said the delivery date was negotiable / so both sides agreed / on a later week that suited the factory.','negotiable 表示条件可以通过讨论调整。','双方协商后改变了日期。'),C('negotiable.s2','可转让或通行','The bank confirmed that the cheque was negotiable, while the guide warned that the flooded trail was no longer negotiable on foot.','银行确认这张支票可以转让；向导则警告说洪水后的步道已无法徒步通行。','The bank confirmed that the cheque was negotiable / while the guide warned / that the flooded trail was no longer negotiable on foot.','negotiable 也可描述可转让的票据或可通行的道路。','同一词在金融与路线语境有专门义项。')],M('The seller called the delivery date negotiable but refused to discuss any change and declared the date permanently fixed.','The seller called the delivery date negotiable and agreed to discuss a later week.','拒绝讨论且固定不变的条件不是可协商的。','meaning'),[q('What did both sides change?','the delivery date','the cheque’s printed amount','the flooded trail’s water level','交货日期经协商改到之后的一周。',1),q('Why could the cheque be called negotiable?','it could be transferred','it could be walked across','it could not be discussed','银行确认支票可以转让。',2,'distinction'),q('Which use means “passable”?','the negotiable trail','the negotiable delivery date','the negotiable price','被洪水淹没的步道已无法通行，说明该义是可通行。',2,'distinction'),q('Negotiable conditions are?','open to discussion and change','fixed forever with no discussion','almost complete','negotiable 可表示条件有商议余地。',1,'meaning')]);
P('negotiate','Negotiate comes through French from Latin negotiari, “to carry on business”; it means to discuss for agreement or to get through a difficult place or situation.',[C('negotiate.s1','谈判达成协议','The union and the hospital negotiated a new shift schedule after nurses explained how the old rota affected patient care.','护士说明旧排班如何影响患者护理后，工会与医院协商制定了新班表。','The union and the hospital negotiated a new shift schedule / after nurses explained / how the old rota affected patient care.','negotiate 作动词表示与他人讨论并达成协议。','双方针对排班问题谈判并形成新安排。'),C('negotiate.s2','顺利通过障碍','The rescue driver negotiated the icy hairpin bends slowly and reached the isolated village before nightfall.','救援司机缓慢驶过结冰的急弯，在天黑前抵达偏远村庄。','The rescue driver negotiated the icy hairpin bends slowly / and reached the isolated village / before nightfall.','negotiate 也可表示成功通过复杂地点或应付困难局面。','司机谨慎通过结冰急弯。')],M('The driver negotiated the icy bends by refusing to steer and letting the vehicle slide off the road.','The driver negotiated the icy bends carefully and kept the vehicle on the road.','失控滑出道路不叫成功通过弯道。','meaning'),[q('What did the union and hospital negotiate?','a new shift schedule','a necktie design','a nebula map','双方协商出新排班表。'),q('How did the rescue driver get through the bends?','slowly and carefully','by abandoning the vehicle','by waiting for summer','司机缓慢通过结冰急弯。',2),q('Which use means reach an agreement?','negotiate a shift schedule','negotiate an icy bend','negotiate a narrow tunnel','排班讨论是协商达成协议。',1,'distinction'),q('Which use means successfully pass an obstacle?','negotiate a steep mountain pass','negotiate a salary offer','negotiate a delivery date','驶过山口属于通过障碍的义项。',2,'distinction')]);
P('negotiation','Negotiation comes from Latin negotium (“business”) through negotiari; it names formal discussion toward agreement or the process or skill of reaching one.',[C('negotiation.s1','正式会谈','After three days of negotiation, the two governments signed an agreement allowing fishing vessels to return to the shared waters.','经过三天谈判，两国政府签署协议，允许渔船返回共同水域。','After three days of negotiation / the two governments signed an agreement / allowing fishing vessels to return to the shared waters.','negotiation 可指为达成协议而进行的正式讨论。','谈判最终产生书面协议。'),C('negotiation.s2','谈判过程技巧','The course teaches negotiation by having students practise listening, proposing alternatives, and recording each side’s priorities.','这门课程让学生练习倾听、提出替代方案并记录双方重点，以教授谈判过程和技巧。','The course teaches negotiation / by having students practise listening / proposing alternatives / and recording each side’s priorities.','negotiation 也可指达成协议的过程或谈判能力。','课程训练谈判者的具体步骤与技能。')],M('The negotiation ended with a signed agreement, but the report said the parties had reached no agreement or decision.','The negotiation ended with a signed agreement on shared fishing waters.','签署协议说明谈判达成了结果，并非没有协议。','meaning'),[q('What did the governments sign?','an agreement about shared fishing waters','a monthly theatre programme','a necktie pattern','三天谈判后签署了协议。'),q('What skills do students practise?','listening and proposing alternatives','mending a fishing net only','measuring a nebula','课程练习倾听和提出替代方案。',2),q('Which is an example of a negotiation process?','both sides compare proposals and revise terms','one side announces a decision with no discussion','a scientist measures a nerve','谈判过程包括交换和修改提议。',2,'distinction'),q('Negotiation is related to which verb?','negotiate','neglect','neaten','negotiation 指 negotiate 的会谈或过程。',1,'word-formation')]);
P('negro','Negro entered English from Spanish or Portuguese negro, “black,” ultimately from Latin niger; it is a dated racial term and is not a neutral contemporary label.',C('negro.s1','历史语域','The museum retained “Negro” only when transcribing the wording of an early census and explained that the term is dated.','博物馆只在转录早期人口普查原文时保留“Negro”，并说明该词已经过时。','The museum retained “Negro” only when transcribing the wording of an early census / and explained / that the term is dated.','该词是过时的种族称呼；当代叙述应采用 Black 或当事人偏好的表述。','词仅作为历史档案原文引用，并明确标出时代语域。'),M('The journalist used Negro as an unmarked, neutral label for a person in a current report.','The journalist used the person’s preferred contemporary description and quoted Negro only when discussing a historical record.','该词已过时且可能冒犯；不应作为现代中性称呼。','register'),[q('Why did the museum retain the term in its display?','it was transcribing an early census exactly','it considered the term a current neutral label','it was naming a necktie','博物馆只在忠实转录历史原文时保留该词。',1,'context'),q('How is the term described for present-day usage?','dated and not a neutral contemporary label','the preferred neutral term in every report','a scientific word for a nebula','条目明确标注该词过时，不是现代中性称呼。',1,'register'),q('What is the respectful approach in a current report?','use Black or the person’s preferred description','use an outdated label without context','replace names with insults','现代写作应采用当事人认可或当前通行的称呼。',1,'register'),q('Where may the old term appear in the example?','inside a clearly identified historical quotation','as an unmarked label for a current person','as the title of a current medical diagnosis','例句只在说明历史记录时引用原词。',1,'context')]);
P('neighbor','Neighbor is from Old English nēahgebūr, literally a “near dweller”; it names a nearby person or country and can mean to be next to something. The spelling neighbor is American.',[C('neighbor.s1','邻居','Our neighbor brought the parcel inside during the storm and left a note so we could collect it after work.','暴风雨期间，邻居把包裹拿进屋并留了张便条，让我们下班后领取。','Our neighbor brought the parcel inside during the storm / and left a note / so we could collect it after work.','neighbor 作名词指住在隔壁或附近的人。','邻居替住户暂时代收包裹。'),C('neighbor.s2','邻近国家或事物','The report compared the river’s water quality with that of its neighbor, a lake connected by a narrow channel.','报告比较了这条河与其相邻水体——一座由狭窄水道连通的湖泊——的水质。','The report compared the river’s water quality / with that of its neighbor / a lake connected by a narrow channel.','neighbor 也可指相邻的国家或其他事物。','湖泊与河道相连，是河流的邻近水体。'),C('neighbor.s3','相邻动词','The two farm fields neighbor each other, sharing a fence along the northern boundary.','两块农田彼此相邻，北侧边界共用一道围栏。','The two farm fields neighbor each other / sharing a fence / along the northern boundary.','neighbor 作动词表示位于某处旁边或与其相邻。','共用边界说明两块田相邻。')],M('The farmer said the fields neighbor each other although a wide ocean lies between them.','The farmer said the fields neighbor each other because they share a boundary fence.','彼此隔着大洋的田地不能称为相邻。','meaning'),[q('What did the neighbor do with the parcel?','brought it inside during the storm','sent it to a nebula','used it as a necktie','邻居在暴雨中帮忙收进包裹。'),q('What was the river’s neighbor?','a connected lake','a distant planet','a motor race','报告把相连的湖称为河流的邻近水体。',2),q('Which sentence uses neighbor as a verb?','The fields neighbor each other.','Our neighbor collected the parcel.','The river has a neighbor.','neighbor 作动词表示两个地点相邻。',3,'grammar'),q('Which spelling is American English?','neighbor','neighbour','neighboor','neighbor 是美式拼法。',1,'spelling')]);
P('neighborhood','Neighborhood is neighbor plus -hood and names a local area where people live or the surrounding vicinity; this is the American spelling.',C('neighborhood.s1','社区街区','The neighborhood organised a weekend clean-up and asked residents to clear litter from the park and bus stop.','社区组织周末清洁活动，请居民清理公园和公交站的垃圾。','The neighborhood organised a weekend clean-up / and asked residents / to clear litter from the park and bus stop.','neighborhood 可指人们居住的街区或当地居民群体。','居民共同组织社区活动。'),M('The neighborhood held a local clean-up, but the report said the event involved residents from an unrelated continent with no local connection.','Residents in the neighborhood organised a clean-up of their own park and bus stop.','neighborhood 指本地街区或社区居民，不是无关的远方群体。','meaning'),[q('What did the neighborhood organise?','a weekend clean-up','a negotiation over a river','a telescope survey','社区组织周末清洁活动。'),q('Which places were residents asked to clean?','the park and bus stop','a distant planet and its moon','a clinic freezer','活动清理公园和公交站。'),q('Neighborhood refers to?','a local area or its community','only one person living next door','a grammatical negation','neighborhood 指当地街区或居住社区。',1,'meaning'),q('Which spelling is American English?','neighborhood','neighbourhood','neighberhood','neighborhood 是美式拼法。',1,'spelling')]);
P('neighboring','Neighboring is neighbor plus -ing and means next door or nearby, especially of a place or country; it is the American spelling.',C('neighboring.s1','邻近地区','A neighboring village opened its school gym as a temporary shelter for families displaced by the flood.','邻近村庄开放学校体育馆，作为洪水中转移家庭的临时避难所。','A neighboring village opened its school gym / as a temporary shelter / for families displaced by the flood.','neighboring 作形容词表示地理上紧邻或靠近。','村庄距离很近，能提供应急收容。'),M('The aid team called a settlement on another continent the neighboring village of the flooded town.','The aid team called the village a few miles away a neighboring village.','远在另一大陆的聚落不是该镇的邻近村庄。','meaning'),[q('What did the neighboring village provide?','a temporary shelter','a smooth nectarine','a nerve cell','邻近村开放体育馆收容受灾家庭。'),q('What does neighboring describe?','a nearby place or country','a person’s state of poverty','a tiny effect','neighboring 表示地点或国家邻近。',1),q('Which place can be called neighboring?','a village a few miles from the town','a settlement on another continent','a star-forming nebula','近在数英里外的村庄属于邻近地区。',1,'context'),q('Which spelling is American English?','neighboring','neighbouring','neighborring','neighboring 是美式拼法。',1,'spelling')]);
P('neighbourhood','Neighbourhood is the British spelling of neighborhood, formed from neighbour plus -hood; it means a town area or the people who live there.',C('neighbourhood.s1','英国英语街区','The neighbourhood held a residents’ meeting in the church hall to discuss safer crossings near the primary school.','这个街区在教堂大厅召开居民会议，讨论小学附近更安全的过街设施。','The neighbourhood held a residents’ meeting / in the church hall / to discuss safer crossings near the primary school.','neighbourhood 指城镇中的一个区域，也可指当地居民。','居民共同讨论社区道路问题。'),M('The British council wrote neighbourhood but used it to mean a single person who lives next door.','The British council used neighbourhood for the local area and its residents.','neighbourhood 指区域或居民群体，不是单独一个邻居。','distinction'),[q('Where did residents meet?','in the church hall','inside a freezer','on a motorway','居民会议在教堂大厅举行。'),q('What did the meeting discuss?','safer crossings near the primary school','how to transfer a cheque','the life of a neuron','他们讨论小学附近的安全过街设施。'),q('Neighbourhood can refer to?','a local town area or its residents','only a person living next door','a smooth-skinned peach','neighbourhood 指街区或其居民群体。',1,'meaning'),q('Neighbourhood is standard spelling in?','British English','American English only','Latin','neighbourhood 是英式拼法，美式通常写 neighborhood。',1,'spelling')]);
P('neighbouring','Neighbouring is the British spelling of neighboring and describes a place or country that is next to or very near another.',C('neighbouring.s1','英式邻近形容词','The neighbouring county sent fire crews to help contain the wildfire before it reached the border villages.','邻县派出消防队协助控制山火，避免火势蔓延到边境村庄。','The neighbouring county sent fire crews / to help contain the wildfire / before it reached the border villages.','neighbouring 作形容词表示与某地相邻或相距很近。','邻县及时派队支援。'),M('The report described a country on the other side of the ocean as neighbouring to the local county.','The report described the county beside it as neighbouring.','隔着大洋的国家并非当地县的邻近地区。','meaning'),[q('Who sent fire crews?','the neighbouring county','a distant island country','the local nectar farm','邻县派消防队支援。'),q('What danger were crews trying to contain?','a wildfire','a neck injury','a leaking freezer','他们协助控制山火。'),q('Which region is neighbouring?','a county sharing a border','a country across an ocean','a galaxy far away','接壤的县属于邻近地区。',1,'context'),q('Neighbouring is the usual spelling in?','British English','American English only','Greek','neighbouring 是英式拼法。',1,'spelling')]);
P('neither','Neither is from Old English nāhwæðer, literally “not either”; it can mean not one nor the other, serve as a pronoun, add a matching negative, or pair with nor.',[C('neither.s1','两者都不','Neither route was safe during the storm: one crossed a flooded bridge and the other passed beneath a landslide slope.','暴风雨期间两条路线都不安全：一条经过被淹的桥，另一条经过有滑坡风险的山坡下方。','Neither route was safe during the storm / one crossed a flooded bridge / and the other passed beneath a landslide slope.','neither + 单数名词表示两者中任何一个都不符合。','两条路线都有危险，因此两者都不安全。'),C('neither.s2','代词用法','“Which key opens the cabinet?” “Neither; both keys belong to the filing room.”','“哪把钥匙能打开柜子？”“两把都不能；它们都属于档案室。”','“Which key opens the cabinet?” / “Neither; both keys belong to the filing room.”','neither 可独立作代词，表示两者中无一个。','回答 neither 表示两把钥匙都不合用。'),C('neither.s3','也不','She did not sign the form, and her colleague did not either; neither did the supervisor.','她没有在表格上签字，同事也没有；主管也没签。','She did not sign the form / and her colleague did not either / neither did the supervisor.','句首 neither 可倒装，补充一个相同的否定事实。','主管也没有签字，与前面的否定一致。'),C('neither.s4','neither...nor','The review found neither the bridge nor the bypass safe for heavy lorries until repairs were complete.','评审发现，在维修完成前，桥梁和绕行路都不适合重型卡车通行。','The review found neither the bridge nor the bypass safe / for heavy lorries / until repairs were complete.','neither...nor 连接两个否定选项，意为既不……也不……。','桥和绕行路两者均不安全。')],M('Neither route was safe means one route was safe and the other was dangerous.','Neither route was safe means both routes were unsafe.','neither 否定两者中的任一个，不表示其中一个安全。','meaning'),[q('Why was neither route safe?','both had serious hazards','one was dry and one was open','neither route existed','两条路线都有危险。',1),q('What does the one-word answer Neither mean about the keys?','neither key opens the cabinet','both keys open it','one key opens it','代词 neither 表示两把都不行。',2),q('What does Neither did the supervisor add?','the supervisor also did not sign','the supervisor signed twice','the supervisor opened a cabinet','句首 neither did 补充相同的否定。',3,'grammar'),q('Which structure means “not this one and not that one”?','neither ... nor','either ... or','both ... and','neither...nor 连接两个否定项。',4,'grammar')]);
P('nekton','Nekton was coined in biological science from Greek nektos, “swimming”; it collectively names actively swimming aquatic organisms, as distinct from plankton.',C('nekton.s1','海洋生物群','The survey recorded tuna, squid, and other nekton that could swim against the current rather than drift with it.','调查记录了金枪鱼、鱿鱼等自游生物；它们能逆流游动，而不是随水漂浮。','The survey recorded tuna, squid, and other nekton / that could swim against the current / rather than drift with it.','nekton 指能主动游动的水生生物群，与浮游生物相对。','金枪鱼和鱿鱼主动逆流游动。'),M('The biologist classified drifting plankton as nekton because the organisms could not swim independently against currents.','The biologist classified actively swimming tuna and squid as nekton.','随流漂浮的生物属于 plankton，不是能主动游动的 nekton。','distinction'),[q('Which animals were recorded as nekton?','tuna and squid','organisms drifting passively with the current','land plants','调查记录了主动游动的鱼和鱿鱼。',1),q('What can nekton do that plankton generally cannot?','swim actively against a current','remain a cloud of dust','form a necktie knot','nekton 能主动游动，而不是随流漂浮。',1,'distinction'),q('Which organism best fits nekton?','a fish swimming across a current','a tiny organism carried wherever water flows','a flower producing nectar','主动游动的鱼属于 nekton。',1,'context'),q('The Greek source nektos is associated with?','swimming','negation','neatness','nekton 的希腊词源与游动有关。',1,'word-formation')]);
P('neoclassical','Neoclassical combines neo- (“new”) and classical; it describes a revival of Greek and Roman art or a theory that develops classical economic ideas.',[C('neoclassical.s1','古典艺术复兴','The museum’s neoclassical entrance used balanced columns and a triangular pediment inspired by Greek temples.','博物馆的新古典主义入口采用对称立柱和三角山花，灵感来自希腊神庙。','The museum’s neoclassical entrance used balanced columns / and a triangular pediment / inspired by Greek temples.','艺术中的 neoclassical 指重新借鉴古希腊、古罗马风格。','柱式与山花体现古典建筑复兴。'),C('neoclassical.s2','经济理论','The paper applies a neoclassical model to explain how consumers respond when the price of electricity rises.','论文运用新古典经济模型解释电价上涨时消费者如何作出反应。','The paper applies a neoclassical model / to explain how consumers respond / when the price of electricity rises.','neoclassical 也修饰建立在古典观点上的经济理论。','模型分析价格变化对消费者选择的影响。')],M('The historian called a building neoclassical even though its design rejected classical forms and imitated a medieval fortress.','The historian called the columned, pedimented building neoclassical because it revived Greek and Roman forms.','拒绝古典风格并模仿中世纪城堡，不符合新古典主义建筑特征。','distinction'),[q('What architectural features inspired the entrance?','Greek temple columns and a pediment','a flooded bridge and bypass','a needlefish’s jaws','立柱和三角山花体现希腊神庙风格。',1),q('What does the paper’s model explain?','consumer responses to higher electricity prices','how a bee collects nectar','why a railway station is nearby','论文分析电价变化与消费者反应。',2),q('Which subject is an artistic neoclassical example?','a building reviving Greek and Roman design','a theory of consumer choices','a group of actively swimming fish','古希腊罗马建筑形式复兴属于艺术义。',1,'distinction'),q('Neo- contributes the meaning?','new or revived','not either','small and unimportant','neo- 表示新、复兴。',1,'word-formation')]);
P('neolithic','Neolithic combines Greek neos (“new”) and lithos (“stone”); it describes the later Stone Age and can jokingly mean extremely old-fashioned.',[C('neolithic.s1','新石器时代','The Neolithic settlement contained polished stone tools and grain stores, evidence that its inhabitants farmed the surrounding land.','新石器时代聚落中发现磨制石器和谷仓，说明居民耕种周围土地。','The Neolithic settlement contained polished stone tools and grain stores / evidence that its inhabitants farmed / the surrounding land.','Neolithic 指石器时代后期，人们使用磨制石器并发展农业。','农耕和磨制工具符合新石器时代特征。'),C('neolithic.s2','戏谑陈旧','The reviewer called the office’s paper-only filing rule neolithic, joking that it belonged in a much earlier age.','评论者戏称办公室只收纸质文件的规定“新石器时代”，意思是它陈旧得过分。','The reviewer called the office’s paper-only filing rule neolithic / joking that it belonged / in a much earlier age.','neolithic 可戏谑地形容极其落后或过时的做法。','评语是在讽刺纸质流程过时，不是在谈史前时代。')],M('The archaeologist called a settlement Neolithic because it used polished stone tools and farming, then said this meant its rules were merely outdated paperwork.','The archaeologist used Neolithic for the prehistoric farming settlement; the reviewer used it jokingly for an outdated office rule.','考古学术语与戏谑比喻是两个不同用法，不能把史前聚落等同于陈旧办公室规则。','distinction'),[q('What evidence did the settlement contain?','polished stone tools and grain stores','electricity bills and plastic files','a motor race track','磨制工具和储粮反映新石器时代农耕。',1),q('Why did the reviewer call the filing rule neolithic?','it seemed extremely old-fashioned','it was made of polished stone','it helped the office farm grain','这里是戏谑地批评流程过时。',2),q('Which use is archaeological?','a Neolithic farming settlement','a neolithic paper-only policy used as a joke','a neoclassical column','史前聚落属于历史时期义。',1,'distinction'),q('What do Greek neo- and lithos mean?','new and stone','near and house','nerve and cell','Neolithic 由“新”和“石”构成。',1,'word-formation')]);
P('neon','Neon was named from Greek neos, “new,” when the element was identified in 1898; it is a noble gas that glows reddish-orange in a discharge tube.',C('neon.s1','化学元素','The laboratory passed an electric discharge through neon in a sealed tube, producing the familiar reddish-orange glow.','实验室让电流通过密封管中的氖气，产生熟悉的橙红色光。','The laboratory passed an electric discharge through neon / in a sealed tube / producing the familiar reddish-orange glow.','neon 是元素氖，通电后在放电管中发出橙红色光。','密封放电管中氖气受激发光。'),M('The sign maker filled the tube with neon and expected it to glow bright green without electricity.','The sign maker passed electricity through neon in a tube to produce its reddish-orange glow.','氖的典型放电光是橙红色，且需要电放电激发。','meaning'),[q('What colour did the neon tube produce?','reddish-orange','dark blue with no electricity','green from a flower','氖在放电管中发出橙红光。'),q('What caused the glow?','an electric discharge through neon','a polished stone tool','a nearby river','电流通过氖气产生光。',1),q('Neon is a?','noble gas element','kind of peach','type of fish','neon 是一种惰性气体元素。',1,'meaning'),q('Why was the element called neon?','its name comes from Greek for “new”','it glows only near a necktie','it was named after a neighbour','neon 名称来自希腊语“新”。',1,'word-formation')]);
P('neonate','Neonate is a medical formation from neo- (“new”) and Latin natus (“born”); it means an infant in the neonatal period, usually the first 28 days.',C('neonate.s1','新生儿医学','The neonate remained in the hospital’s observation unit for the first week because the birth had been premature.','这名新生儿因早产在医院观察病房留院一周。','The neonate remained in the hospital’s observation unit / for the first week / because the birth had been premature.','neonate 是医学用语，通常指出生后最初二十八天内的婴儿。','早产儿在出生后第一周接受观察。'),M('The clinic recorded a ten-year-old child as a neonate because the child had just changed schools.','The clinic recorded the infant in the first weeks after birth as a neonate.','转学儿童不是新生儿；neonate 指出生后的婴儿。','meaning'),[q('Why was the neonate observed in hospital?','the infant had been born prematurely','the child was ten years old','the child had a neat school uniform','早产儿在医院接受观察。'),q('A neonate is usually in which period?','the first 28 days after birth','the first 28 years of life','the last month before birth only','neonate 通常指出生后前28天的婴儿。',1,'measurement'),q('Which patient is a neonate?','a baby born two weeks ago','a child aged ten','an adult born in another country','两周大的婴儿属于新生儿期。',1,'context'),q('The parts neo- and natus point to?','newly born','not either','near a dwelling','词形表示“新近出生”。',1,'word-formation')]);
P('nephew','Nephew came through Old French neveu from Latin nepos, “grandchild or nephew”; it means the son of one’s sibling or a spouse’s sibling.',[C('nephew.s1','兄弟姐妹之子','Her nephew, her sister’s son, helped carry the books into the new classroom before lessons began.','她的外甥——她姐姐的儿子——在上课前帮忙把书搬进新教室。','Her nephew, her sister’s son, helped carry the books / into the new classroom / before lessons began.','nephew 指兄弟或姐妹的儿子。','姐姐的儿子是她的 nephew。'),C('nephew.s2','姻亲侄甥','At the reunion, she met her husband’s nephew for the first time; he was the son of her husband’s brother.','家庭聚会上，她第一次见到丈夫的侄子；他是丈夫兄弟的儿子。','At the reunion / she met her husband’s nephew for the first time / he was the son of her husband’s brother.','nephew 也可指配偶的兄弟姐妹的儿子。','丈夫兄弟的儿子属于姻亲侄甥。')],M('She called her sister’s daughter her nephew and introduced the child as a boy.','She called her sister’s son her nephew.','nephew 指兄弟姐妹的儿子；女儿通常称 niece。','confusable'),[q('Who helped carry the books?','her sister’s son','her sister’s daughter','her husband’s aunt','姐姐的儿子帮忙搬书。',1),q('Whose son was the husband’s nephew?','the husband’s brother','the husband’s teacher','the speaker’s neighbour','丈夫的侄子是丈夫兄弟的儿子。',2),q('A nephew is the son of one’s?','sibling or spouse’s sibling','own child','cousin only','nephew 指兄弟姐妹或配偶兄弟姐妹的儿子。',1,'meaning'),q('What word usually means a sibling’s daughter?','niece','nephew','neonate','nephew 是男性，女性对应词是 niece。',1,'confusable')]);
P('Neptune','Neptune was the Roman god of the sea; the planet was named after him and is the eighth planet from the Sun.',[C('Neptune.s1','行星','The spacecraft’s images of Neptune showed deep blue cloud bands around the eighth planet from the Sun.','探测器拍摄的海王星图像显示，第八颗行星周围有深蓝色云带。','The spacecraft’s images of Neptune showed deep blue cloud bands / around the eighth planet / from the Sun.','Neptune 作专名指太阳系第八颗行星海王星。','行星位置和蓝色云带指向海王星。'),C('Neptune.s2','罗马神祇','In the sculpture, Neptune holds a trident and stands beside waves, representing the Roman god of the sea.','雕塑中的海王手持三叉戟立于海浪旁，代表罗马海神。','In the sculpture / Neptune holds a trident and stands beside waves / representing the Roman god of the sea.','Neptune 也指罗马神话中的海神，相当于希腊神话的波塞冬。','三叉戟与海浪是海神的形象标志。')],M('The astronomy guide said Neptune was the Roman sea god, so it must be the planet closest to the Sun.','The astronomy guide said Neptune was the eighth planet from the Sun, named after the Roman sea god.','神话角色的名字来自海神，但该行星远在太阳系外侧。','distinction'),[q('Which planet did the spacecraft image?','the eighth planet from the Sun','the nearest planet to the Sun','Earth’s moon','Neptune 是太阳系第八颗行星。'),q('What does the sculpture’s Neptune hold?','a trident','a pressure gauge','a necktie','罗马海神雕像手持三叉戟。',2),q('Which sense is a deity?','the Roman god of the sea','the eighth planet from the Sun','a cloud of gas and dust','雕塑中的 Neptune 指罗马海神。',2,'distinction'),q('The Greek counterpart of Roman Neptune is?','Poseidon','Apollo','Hermes','Neptune 对应希腊神话海神波塞冬。',2,'word-formation')]);
P('nerve','Nerve came through French from Latin nervus, “sinew,” related to Greek neuron; it can be a signal-carrying fibre, courage, impudence, or the act of emboldening someone.',[C('nerve.s1','神经纤维','The damaged nerve in her hand slowed the signals that normally tell her fingers when to grip a cup.','她手部神经受损，通常提示手指握住杯子的信号因此变慢。','The damaged nerve in her hand slowed the signals / that normally tell her fingers / when to grip a cup.','nerve 指在大脑与身体其他部位之间传递信号的纤维。','神经信号控制手指抓握。'),C('nerve.s2','勇气','It took nerve for the junior engineer to report the safety flaw to senior managers before the public demonstration.','初级工程师在公开演示前向高级经理报告安全缺陷，需要很大的勇气。','It took nerve for the junior engineer / to report the safety flaw / to senior managers / before the public demonstration.','take nerve 表示做困难或令人畏惧的事需要勇气。','向管理层报告问题可能令人畏惧。'),C('nerve.s3','厚颜放肆','The contractor had the nerve to demand a bonus after missing the deadline and leaving the site unfinished.','承包商误了期限、留下未完工现场后，竟厚着脸皮要求奖金。','The contractor had the nerve to demand a bonus / after missing the deadline / and leaving the site unfinished.','have the nerve to 可表示令人惊讶的厚颜或放肆。','未完成工作还索要奖金显得无礼。'),C('nerve.s4','鼓起勇气','She nerved herself to ask the panel a difficult question, although her voice shook at first.','尽管起初声音发抖，她还是鼓起勇气向评审组提出一个棘手问题。','She nerved herself to ask the panel a difficult question / although her voice shook at first.','nerve 可作动词，表示使自己或别人鼓起勇气去做某事。','她克服紧张并提出难题。')],M('The surgeon called the signal-carrying fibre a nerve but said it had no role in carrying messages between body and brain.','The surgeon described the damaged nerve as a fibre that carries messages between the brain and body.','神经的重要功能之一就是传递身体信号。','meaning'),[q('What did the damaged hand nerve slow?','signals telling her fingers to grip','the engineer’s courage','the contractor’s bonus','神经受损减慢了传递给手指的信号。',1),q('What took nerve from the junior engineer?','reporting a safety flaw to senior managers','asking for a bonus after missing a deadline','gripping a cup','报告安全问题需要勇气。',2),q('What did the contractor have the nerve to do?','demand a bonus despite unfinished work','report a safety flaw','repair the damaged nerve','他未按时完成却要求奖金，表现出厚颜。',3),q('What did she nerve herself to do?','ask the panel a difficult question','leave the site unfinished','slow signals in her hand','nerve oneself 表示鼓起勇气去做某事。',4,'grammar')]);
P('nervous','Nervous came through French from Latin nervosus, “sinewy or vigorous,” from nervus (“sinew”); today it commonly means worried or slightly afraid.',C('nervous.s1','紧张焦虑','She felt nervous before the oral exam, so she practised her opening answer with a friend in the library.','口试前她感到紧张，于是在图书馆和朋友练习开场回答。','She felt nervous before the oral exam / so she practised her opening answer / with a friend in the library.','nervous 表示担心或有些害怕，常用于考试、演讲等情境。','她在口试前练习，是因为感到紧张。'),M('She felt nervous before the oral exam, meaning she was completely calm and had no concern about it.','She felt nervous before the oral exam because she was worried about speaking.','担心考试和完全平静相矛盾。','meaning'),[q('When did she feel nervous?','before the oral exam','after receiving her final score','while buying a nectarine','她在口试前感到紧张。'),q('What did she do to prepare?','practised her opening answer with a friend','built a neural network','collected nectar','她和朋友练习了开场回答。'),q('A nervous person is usually?','worried or slightly afraid','completely certain and unworried','a person who studies nerves professionally','nervous 通常表示焦虑或有些害怕。',1,'meaning'),q('Which situation might make someone nervous?','speaking before an examination panel','folding a familiar towel at home','reading a known street sign','在评审组面前发言可能令人紧张。',1,'context')]);
P('nest','Nest continues Old English nest; it can be an animal’s shelter, a safe home or set of fitting objects, or the act of building or placing things together.',[C('nest.s1','动物巢穴','The blackbird carried twigs to a nest hidden in the hedge, where two chicks waited for food.','乌鸫把树枝叼进藏在树篱中的鸟巢，两只雏鸟正在里面等食物。','The blackbird carried twigs to a nest hidden in the hedge / where two chicks waited / for food.','nest 作名词指鸟、昆虫或其他动物养育幼崽的巢穴。','巢里有等待喂食的雏鸟。'),C('nest.s2','安乐窝或套叠物','After the move, the family made a nest in the small attic room, and the kitchen cupboard held a nest of mixing bowls.','搬家后，一家人在小阁楼安了一个温馨的小窝，厨房橱柜里则放着一套可套叠的搅拌碗。','After the move / the family made a nest in the small attic room / and the kitchen cupboard held a nest of mixing bowls.','nest 可比喻舒适的家，也可指一套彼此套入的物品。','阁楼成了舒适居所，搅拌碗可以一只套一只。'),C('nest.s3','筑巢或嵌套','The herons nested on the island, while the designer nested smaller maps inside the larger regional chart.','苍鹭在岛上筑巢；设计师则把小地图嵌套在较大的区域图中。','The herons nested on the island / while the designer nested smaller maps / inside the larger regional chart.','nest 作动词可指筑巢，也可表示把同类物品放进较大的物品中。','动物筑巢与地图嵌套展示两个动词义。')],M('The blackbird carried twigs to its nest but left the chicks exposed on an open road far from any shelter.','The blackbird built a nest in the hedge to shelter its chicks.','巢穴的作用是为动物或幼崽提供庇护。','meaning'),[q('What did the blackbird carry to its nest?','twigs','mixing bowls','regional maps','鸟把树枝叼进树篱中的巢。'),q('What did the family make in the attic room?','a comfortable home','a bird’s nest with chicks','a map nested in a chart','nest 在此比喻舒适的家。',2),q('Which use is a verb meaning put one object inside another?','nested smaller maps inside a chart','built a nest for chicks','made a nest in an attic','地图被嵌套在较大的图中。',3,'grammar'),q('Which item is a nest of objects?','mixing bowls that fit inside one another','one bowl too large for a cupboard','a bird flying over an island','一套彼此套叠的碗可称 nest。',2,'distinction')]);
P('nestle','Nestle is related to nest and means to sit or lie in a warm sheltered position, or to place someone or something there.',[C('nestle.s1','依偎安卧','The kitten nestled beneath the wool blanket beside the radiator until the room warmed up.','房间暖和起来前，小猫一直依偎在暖气旁的羊毛毯下面。','The kitten nestled beneath the wool blanket / beside the radiator / until the room warmed up.','nestle 作不及物动词表示舒适地依偎或安卧在遮蔽处。','毯子和暖气旁提供温暖庇护。'),C('nestle.s2','安放在柔软处','She nestled the sleeping baby into a padded cot and checked that the blanket stayed below the child’s face.','她把熟睡的婴儿轻轻安放进带垫子的婴儿床，并确认毯子没有盖住孩子的脸。','She nestled the sleeping baby into a padded cot / and checked / that the blanket stayed below the child’s face.','nestle 作及物动词表示把人或物放进柔软、安全的位置。','婴儿被安放在有软垫的安全小床中。')],M('The kitten nestled in a warm blanket by jumping into an exposed icy ditch far from shelter.','The kitten nestled beneath a warm blanket beside the radiator.','寒冷无遮蔽的沟渠不符合依偎在温暖安全处的含义。','meaning'),[q('Where did the kitten settle?','beneath a wool blanket by the radiator','in an exposed icy ditch','inside a mixing bowl','小猫躺在暖气旁的毯子下。'),q('Where did she place the sleeping baby?','in a padded cot','on an exposed road','inside a map','婴儿被安放进带垫子的婴儿床。',2),q('Which use is transitive?','She nestled the baby into a cot.','The kitten nestled beneath a blanket.','The cat nestled by the radiator.','第一句有直接宾语 baby。',2,'grammar'),q('Nestle most nearly suggests?','a warm, sheltered position','a loud public argument','a formal business meeting','nestle 含舒适、受庇护地安卧之意。',1,'meaning')]);
P('net','Net continues Old English nett for mesh; it also names the Internet, describes what remains after deductions, and means to gain or catch.',[C('net.s1','网状物','The fisher repaired a torn net on the pier before lowering it into the shallow bay at dawn.','渔夫在黎明把渔网放进浅海湾前，先在码头修补破洞。','The fisher repaired a torn net on the pier / before lowering it / into the shallow bay at dawn.','net 作名词指由线、绳或金属丝交织而成的网。','渔网被放入海湾捕鱼。'),C('net.s2','互联网','The school posted the timetable on the Net so families could check for changes before travelling.','学校把课程表发到网上，让家长出门前查看是否有变动。','The school posted the timetable on the Net / so families could check for changes / before travelling.','the Net 是 Internet 的非正式简称，通常大写。','家长通过网络查看通知。'),C('net.s3','扣除后的净额','After tax and service fees, her net pay was lower than the amount printed at the top of the offer letter.','扣除税款和服务费后，她的净工资低于录用信顶部列出的金额。','After tax and service fees / her net pay was lower / than the amount printed at the top of the offer letter.','net 作形容词表示扣除税费或包装重量后剩余的净额。','净工资是在扣税费之后计算的。'),C('net.s4','净得或捕获','The sale netted the charity £4,000, and the fishing crew netted enough mackerel for the village meal.','这次义卖为慈善机构净赚四千英镑，渔船也捕到了足够村宴食用的鲭鱼。','The sale netted the charity £4,000 / and the fishing crew netted enough mackerel / for the village meal.','net 作动词可指净赚某金额，也可指用网捕获。','分别展示收入与捕捞两种动词义。')],M('The shop advertised net pay before tax, meaning the amount left after tax and fees had been removed.','The shop advertised gross pay before deductions; net pay is the amount left after tax and fees.','扣税前是 gross pay，net pay 是扣除之后的金额。','distinction'),[q('What did the fisher repair?','a torn mesh net','the school timetable','a tax form','渔夫修补的是渔网。'),q('Where did the school post the timetable?','on the Internet','inside a fishing net','on the offer letter envelope','the Net 指互联网。',2),q('What is net pay?','the amount remaining after deductions','the salary before tax','the weight of a fishing net','net pay 是扣税费后的金额。',3,'distinction'),q('What did the charity sale net?','£4,000 after the sale','a village meal of mackerel','a mesh repaired on the pier','net 作动词表示义卖净赚四千英镑。',4,'grammar')]);
P('nettle','Nettle continues Old English netele; it names a stinging plant and can be a verb meaning to irritate or provoke someone.',[C('nettle.s1','荨麻植物','The hiker brushed against a nettle beside the path and felt a sharp sting on her bare ankle.','徒步者擦到小径旁的荨麻，裸露的脚踝立刻感到刺痛。','The hiker brushed against a nettle beside the path / and felt a sharp sting / on her bare ankle.','nettle 作名词指叶片会刺痛皮肤的野生植物。','碰到荨麻后裸露皮肤刺痛。'),C('nettle.s2','惹恼激怒','The repeated criticism nettled the apprentice, who asked the supervisor to discuss the work calmly.','反复的批评惹恼了学徒，他请求主管平静地讨论工作。','The repeated criticism nettled the apprentice / who asked the supervisor / to discuss the work calmly.','nettle 作动词表示惹恼或激起某人的不快。','不断批评让学徒感到恼火。')],M('The hiker called a harmless smooth leaf a nettle even though it had no stinging hairs and caused no irritation.','The hiker identified the stinging plant beside the path as a nettle.','荨麻的叶片会刺痛皮肤；光滑无刺激的叶子不符合该特征。','distinction'),[q('What happened after the hiker touched the nettle?','her bare ankle felt a sharp sting','the plant produced a necklace','the trail became a motorway','碰到荨麻后脚踝刺痛。'),q('What nettled the apprentice?','repeated criticism','a smooth-skinned peach','a net full of fish','反复批评惹恼了学徒。',2),q('Which sentence uses nettle as a verb?','The criticism nettled the apprentice.','A nettle grew beside the path.','She brushed against a nettle.','第一句 nettled 表示惹恼。',2,'grammar'),q('What can a nettle plant do to skin?','sting it','make it neat','turn it into a neuron','荨麻叶会刺痛皮肤。',1,'meaning')]);
P('nettlesome','Nettlesome combines nettle and -some and means annoying or difficult to settle.',C('nettlesome.s1','恼人难办','The council faced a nettlesome boundary dispute because two old maps placed the footpath on different sides of the stream.','市议会遇到一个棘手的边界争议，因为两张旧地图把小径标在溪流的不同一侧。','The council faced a nettlesome boundary dispute / because two old maps / placed the footpath on different sides of the stream.','nettlesome 可形容恼人或难以解决的问题。','地图冲突使边界问题难以裁定。'),M('The council called the boundary dispute nettlesome although both maps showed the same line and all parties agreed.','The council called the boundary dispute nettlesome because the old maps contradicted each other.','资料一致且无人争议的问题并不麻烦。','meaning'),[q('Why was the boundary dispute difficult?','two old maps showed the path on different sides','the stream had disappeared from both maps','the council had no meeting room','两张旧地图相互矛盾。'),q('Nettlesome most nearly means?','annoying or difficult to settle','simple and already settled','nearly complete','该词描述恼人或难处理的问题。',1),q('Which issue is nettlesome?','a claim that remains unresolved because records conflict','a question everyone has answered','a clear route shown identically on every map','记录冲突且未解决的争议很棘手。',1,'context'),q('Nettlesome is formed from nettle plus?','-some','-hood','-al','-some 构成形容词 nettlesome。',1,'word-formation')]);
P('network','Network combines net and work; it can be an interconnected system, a group of people or computers, or the act of connecting or building contacts.',[C('network.s1','线路系统','The rail network reopened after crews replaced the damaged track linking the northern towns to the port.','维修人员更换了连接北部城镇与港口的受损轨道后，铁路网重新开放。','The rail network reopened / after crews replaced the damaged track / linking the northern towns to the port.','network 作名词指彼此相连的线路、道路或电缆系统。','铁路轨道连接多个城镇与港口。'),C('network.s2','人际或计算机网络','The clinic network lets doctors share test results securely, while a professional network helps researchers find collaborators.','诊所网络让医生安全共享检测结果，专业人际网络则帮助研究人员寻找合作者。','The clinic network lets doctors share test results securely / while a professional network / helps researchers find collaborators.','network 也指交换信息的人群或计算机系统。','两个例子分别是电脑网络与人际网络。'),C('network.s3','联网或建立关系','The engineer networks the sensors across the wetland, and she also networks with local researchers at monthly meetings.','工程师把湿地各处的传感器连接成网，也在每月会议上与当地研究人员建立联系。','The engineer networks the sensors across the wetland / and she also networks with local researchers / at monthly meetings.','network 作动词可连接计算机设备，也可表示结识并交流信息。','句中分别用到技术联网和建立人脉。')],M('The rail network reopened after every track connection was removed and the northern towns were isolated from the port.','The rail network reopened after crews repaired the track connecting the towns with the port.','拆除所有连接会让线路不再构成相连的铁路网。','meaning'),[q('Which places did the repaired track connect?','northern towns and the port','the clinic and a necklace shop','two planets','轨道连接北部城镇与港口。'),q('What can doctors share through the clinic network?','test results','fishing nets','morris costumes','诊所网络让医生安全共享检测结果。',2),q('Which use is a verb about professional contacts?','She networks with local researchers.','A rail network reopened.','The clinic network stores results.','与研究人员交流建立联系是动词 network。',3,'grammar'),q('A network is generally?','a group of connected parts that exchange or carry something','one isolated item with no links','a person’s anxious feeling','network 指互相连接的系统或群体。',1,'meaning')]);
P('networking','Networking is network plus -ing and means building professional contacts or connecting computers and systems.',[C('networking.s1','人际联络','At the conference, networking helped the early-career scientists find a laboratory willing to share equipment.','会议上的人际交流帮助初入行的科学家找到愿意共享设备的实验室。','At the conference / networking helped the early-career scientists / find a laboratory willing to share equipment.','networking 可指通过交流建立联系与合作机会。','结识实验室联系人促成设备共享。'),C('networking.s1','系统联网','The technician completed the networking of the weather stations so their readings could be compared from one control room.','技术员完成了气象站的联网工作，使各站读数能在一个控制室统一比较。','The technician completed the networking of the weather stations / so their readings could be compared / from one control room.','networking 也可指把电脑或设备连接成信息系统。','联网后读数能集中查看。')],M('The conference described networking as refusing to speak to anyone and keeping all research contacts isolated.','The conference described networking as meeting researchers and building useful professional contacts.','拒绝交流并隔离联系人与建立人际联系相反。','meaning'),[q('What did networking help the scientists find?','a laboratory willing to share equipment','a nettle-free garden','a second planet','交流让科学家找到共享设备的实验室。'),q('Why were weather stations networked?','to compare readings from one control room','to make each station isolated','to grow nectar','联网后可统一比较气象读数。',1),q('Which networking is social?','introducing yourself to researchers at a conference','connecting weather stations with data cables','linking computers to a server','在会议上建立研究联系是社交 networking。',1,'distinction'),q('Networking can involve?','building contacts or connecting systems','only a single computer with no links','only a stinging plant','networking 可指人际联络或技术联网。',1,'meaning')]);
P('neural','Neural comes from Greek neuron (“nerve”) plus -al and means relating to nerves or signal pathways in the body or an artificial network.',C('neural.s1','神经信号','The neural pathway carried signals from the patient’s hand to the brain, allowing the team to map the response to touch.','神经通路把患者手部信号传到大脑，让团队能够绘制触觉反应图。','The neural pathway carried signals from the patient’s hand to the brain / allowing the team / to map the response to touch.','neural 作形容词表示与神经或传递信号的通路有关。','句中通路传递手部触觉信号。'),M('The researcher called a railway line neural because trains carried passengers along it.','The researcher called a nerve-signal pathway neural because it carried messages through the nervous system.','铁路运送乘客，不是神经系统中的信号通路。','word-choice'),[q('Where did the neural pathway carry signals?','from the hand to the brain','from the port to the northern towns','from a flower to a hive','神经通路把手部信号传向大脑。'),q('What response did the team map?','the response to touch','the response to nectar','the response to a necktie','研究团队绘制触觉反应。',1),q('Neural most nearly means?','related to nerves or signal pathways','related to a neighbour’s house','almost complete','neural 指神经的或神经通路相关的。',1,'meaning'),q('Which phrase is neural?','a neural pathway in the nervous system','a neat shelf in a clinic','a neighboring village','神经系统中的信号通路是 neural。',1,'context')]);
P('neuralgia','Neuralgia combines Greek neuron (“nerve”) and algos (“pain”); it means sharp, often recurring pain in an area served by a nerve.',C('neuralgia.s1','神经痛','The doctor recorded neuralgia along the patient’s jaw, where brief sharp pains returned several times each day.','医生记录患者下颌处有神经痛，那里每天会反复出现几次短促刺痛。','The doctor recorded neuralgia along the patient’s jaw / where brief sharp pains / returned several times each day.','neuralgia 指沿某条神经分布区域出现的尖锐、常复发疼痛。','下颌神经区域反复出现刺痛。'),M('The chart labelled a painless bruise neuralgia even though the patient reported no sharp or recurring nerve pain.','The chart labelled the recurring sharp pain along a nerve as neuralgia.','没有疼痛就不符合 neuralgia 的核心含义。','meaning'),[q('Where did the patient feel recurring pain?','along the jaw','in a smooth nectarine','at the railway port','疼痛出现在下颌神经区域。'),q('What was the pain like?','brief, sharp, and recurring','a constant pleasant warmth','a colour change with no sensation','医生记录的是反复短促刺痛。',1),q('Neuralgia is pain associated with?','a nerve','a nettle’s colour only','a neighbourhood','neuralgia 是神经痛。',1,'meaning'),q('Which pattern best fits neuralgia?','sharp pain that returns along a nerve pathway','a painless bruise that fades','a single harmless tickle with no recurrence','沿神经反复出现的尖锐疼痛符合该义。',1,'context')]);
P('neurilemmal','Neurilemmal is neurilemma plus -al; it means relating to the outer sheath surrounding the myelin of a peripheral nerve fibre.',C('neurilemmal.s1','神经膜结构','The biopsy showed damage to the neurilemmal sheath around a peripheral nerve, so the specialist ordered further tests.','活检显示周围神经外的神经膜鞘受损，因此专科医生安排了进一步检查。','The biopsy showed damage to the neurilemmal sheath / around a peripheral nerve / so the specialist ordered further tests.','neurilemmal 是形容词，描述周围神经纤维外的神经膜。','检查发现周围神经外鞘受损。'),M('The report called the neurilemmal sheath a layer of skin covering the outside of the patient’s hand.','The report described the neurilemmal sheath as a covering around a peripheral nerve fibre.','神经膜是神经纤维相关结构，不是手部皮肤。','meaning'),[q('What structure was damaged?','the sheath around a peripheral nerve','the patient’s necktie','a railway signal cable','活检发现周围神经外鞘受损。'),q('Neurilemmal describes something related to?','the outer sheath of a peripheral nerve fibre','the surface of a peach','a nearby district','neurilemmal 指神经膜的。',1),q('Which phrase is correctly matched?','neurilemmal sheath — covering around a peripheral nerve','neurilemmal — a type of city network','neurilemmal — a neck accessory','神经膜鞘围绕周围神经纤维。',1,'meaning'),q('What did the specialist order after the biopsy?','further tests','a motor race','a bowl of nectar','发现结构受损后安排进一步检查。',1,'context')]);
P('neuroglia','Neuroglia combines Greek neuron (“nerve”) and glia (“glue”); it names supporting tissue that protects and insulates neurons.',C('neuroglia.s1','神经支持组织','The lesson explained that neuroglia support neurons and help insulate nerve cells, rather than carrying the main electrical signal themselves.','课程解释说，神经胶质支持并绝缘神经元，而不是由它们承担主要电信号传递。','The lesson explained that neuroglia support neurons / and help insulate nerve cells / rather than carrying the main electrical signal themselves.','neuroglia 指支持、保护并绝缘神经元的胶质组织。','句子区分支持作用与神经元主要信号传递作用。'),M('The textbook said neuroglia were the only cells that carried every nerve signal while neurons merely insulated them.','The textbook said neuroglia support and insulate neurons, which carry electrical signals.','把主要信号传递和支持绝缘功能对调了。','meaning'),[q('What do neuroglia do?','support and insulate neurons','form a necklace around the neck','collect nectar from flowers','神经胶质支持并绝缘神经元。'),q('Which cells carry electrical signals in the example?','neurons','neuroglia only','nettles','句中说明神经元承担电信号传递。',1),q('Neuroglia are best described as?','supporting tissue for nerve cells','a kind of neuralgia','a group of swimming fish','neuroglia 是神经系统中的支持组织。',1,'meaning'),q('The Greek element glia contributes the idea of?','glue or supporting material','pain','a new birth','glia 的词源含“胶”义。',1,'word-formation')]);
P('neurological','Neurological is neurology plus -ical and means concerning the brain, spinal cord, or nerves, especially in medical study.',C('neurological.s1','神经系统相关','The patient reported numbness in one arm, so the clinic arranged a neurological examination of sensation and reflexes.','患者报告一只手臂麻木，因此诊所安排了感觉和反射的神经系统检查。','The patient reported numbness in one arm / so the clinic arranged a neurological examination / of sensation and reflexes.','neurological 形容词指与大脑、脊髓或神经有关。','检查针对感觉和反射等神经系统功能。'),M('The clinic called a blood-pressure reading neurological although it assessed only circulation and did not concern the brain, spinal cord, or nerves.','The clinic called the examination neurological because it assessed sensation and reflexes.','仅测血压并不直接检查神经系统。','word-choice'),[q('What symptom led to the examination?','numbness in one arm','a cracked necktie','a stinging nettle in a bowl','患者报告手臂麻木。'),q('What did the exam assess?','sensation and reflexes','the colour of a nebula','the net income after taxes','检查感觉和反射。'),q('Neurological concerns the?','brain, spinal cord, or nerves','skin of a nectarine only','area around a railway station','neurological 指神经系统相关。',1,'meaning'),q('Which appointment is neurological?','an assessment of nerve function and reflexes','a routine neighbourhood clean-up','a negotiation over travel dates','神经功能和反射评估属于神经系统检查。',1,'context')]);
P('neurologist','Neurologist combines neurology and -ist and means a physician trained to diagnose and treat disorders of the brain, spinal cord, and nerves.',C('neurologist.s1','专科医生','The neurologist reviewed the patient’s scan and reflex tests before discussing possible causes of recurring hand numbness.','神经科医生查看了患者的扫描和反射测试后，讨论手部反复麻木的可能原因。','The neurologist reviewed the patient’s scan and reflex tests / before discussing / possible causes of recurring hand numbness.','neurologist 是受过神经系统疾病诊治训练的医师。','医生结合影像与检查结果讨论症状原因。'),M('The patient visited a neurologist to repair a leaking roof because the doctor specialised in buildings rather than the nervous system.','The patient visited a neurologist to assess recurring numbness and nerve function.','neurologist 诊治神经系统问题，不负责房屋维修。','word-choice'),[q('What did the neurologist review?','a scan and reflex tests','a net full of mackerel','a neighborhood map','医生查看扫描结果与反射测试。'),q('Why was the patient referred?','recurring hand numbness','a need for a necktie','a smooth-skinned peach','患者手部反复麻木。',1),q('A neurologist is a physician specialising in?','brain, spinal cord, and nerve disorders','fruit cultivation','railway networks','神经科医生诊治大脑、脊髓和神经疾病。',1,'meaning'),q('Which professional should assess nerve function?','a neurologist','a tailor','a railway dispatcher','神经功能应由神经科医生评估。',1,'context')]);
P('neurology','Neurology combines Greek neuron (“nerve”) and -logy (“study”); it is the medical science concerned with nerves and neurological disease.',C('neurology.s1','医学学科','The hospital expanded its neurology clinic so patients with recurring nerve pain could be assessed by specialists.','医院扩建了神经病学门诊，让反复神经痛患者能接受专科评估。','The hospital expanded its neurology clinic / so patients with recurring nerve pain / could be assessed by specialists.','neurology 是研究神经及相关疾病的医学学科。','门诊为神经痛患者提供专科诊治。'),M('The hospital placed recurring nerve pain in the neurology clinic because neurology studies only flower nectar and not nerves.','The hospital placed recurring nerve pain in the neurology clinic because neurology concerns nerves and their disorders.','neurology 的研究对象正是神经和神经系统疾病。','meaning'),[q('Why did the hospital expand the neurology clinic?','patients with recurring nerve pain needed specialist assessment','families wanted a neighborhood meeting','the rail network needed new track','门诊扩建用于评估神经痛患者。'),q('Neurology is the medical study of?','nerves and neurological disease','fruit and flower nectar','net income','neurology 研究神经系统及其疾病。',1),q('Which topic belongs in neurology?','a disorder affecting nerve function','the shape of a necklace','a road’s negotiable surface','神经功能障碍属于神经病学。',1,'context'),q('The suffix -logy contributes the meaning?','study or field of knowledge','a person who practises medicine','a small amount','-logy 表示学科或研究。',1,'word-formation')]);
P('neuron','Neuron comes from Greek neuron, “sinew or nerve”; it is a cell that carries electrical signals in the brain and nervous system.',C('neuron.s1','神经细胞','The damaged neuron sent weaker electrical signals, which made the patient’s hand respond more slowly to touch.','受损神经元传出的电信号较弱，患者的手对触碰反应也变慢。','The damaged neuron sent weaker electrical signals / which made the patient’s hand / respond more slowly to touch.','neuron 是在大脑和神经系统中传递电信号的细胞。','信号减弱使触觉反应变慢。'),M('The lab called a support cell that insulated nearby neurons a neuron even though it did not carry an electrical signal.','The lab called the signal-carrying nerve cell a neuron and identified the supporting cell as neuroglia.','neuron 负责传递信号；支持绝缘细胞属于 neuroglia。','distinction'),[q('What happened when the neuron sent weaker signals?','the hand responded more slowly to touch','the patient’s neighborhood became smaller','the net income increased','电信号减弱使手部反应变慢。'),q('A neuron is a cell that carries?','electrical signals','flower nectar','a mortgage','神经元传递电信号。',1),q('Which cell is the neuron in the example?','the signal-carrying nerve cell','the supporting cell that only insulates','a blood cell in a net','传递信号的是神经元，而非绝缘支持细胞。',1,'distinction'),q('Neuron comes from Greek for?','nerve or sinew','new and stone','not either','希腊语 neuron 指神经或筋腱。',1,'word-formation')]);
P('neuroscientist','Neuroscientist combines neuro- (“nervous system”) and scientist; it names a researcher in neuroscience, who is not necessarily a clinician.',C('neuroscientist.s1','神经科学研究者','The neuroscientist compared brain scans from volunteers to study how sleep affects attention and memory.','神经科学家比较志愿者的脑部扫描，研究睡眠如何影响注意力和记忆。','The neuroscientist compared brain scans from volunteers / to study / how sleep affects attention and memory.','neuroscientist 是研究神经科学的研究人员，不一定是临床医生。','志愿者脑扫描用于研究认知功能。'),M('The neuroscientist prescribed surgery to every volunteer because the title always means a physician treating patients.','The neuroscientist studied brain scans as a researcher; a clinician would make treatment decisions.','神经科学家通常指研究人员，并不必然是临床医师。','distinction'),[q('What did the neuroscientist compare?','brain scans from volunteers','neckties from doctors','nets from fishers','研究者比较志愿者脑扫描。'),q('What did the research study?','effects of sleep on attention and memory','how to negotiate a cheque','how a nectarine grows smooth skin','研究关注睡眠对注意力和记忆的影响。',1),q('A neuroscientist is necessarily?','a researcher, not necessarily a clinician','a surgeon in every case','a person with neuralgia','neuroscientist 指研究者，不必然是临床医生。',1,'distinction'),q('Which work fits a neuroscientist?','analysing brain scans to study memory','repairing a neighbourhood roof','negotiating a motor race schedule','分析脑扫描以研究记忆属于神经科学研究。',1,'context')]);
P('neurosis','Neurosis is a medical term formed from neuro- (“nerve”) and -osis; older usage names an anxiety condition, and it can also refer to nervous or unreasonable worry.',[C('neurosis.s1','焦虑性心理状况','An older case note used neurosis for the patient’s persistent anxiety and unreasonable fears, while a modern assessment would specify the diagnosis.','一份旧病历用 neurosis 描述患者持续的焦虑和不合理恐惧；现代评估会进一步明确具体诊断。','An older case note used neurosis for the patient’s persistent anxiety and unreasonable fears / while a modern assessment / would specify the diagnosis.','neurosis 是较旧的心理学术语，指伴有焦虑或不合理恐惧的心理状况。','历史病历使用旧分类，现代诊断更具体。'),C('neurosis.s2','日常神经质表现','His repeated checking of the locked door became a minor neurosis, though he knew the habit was excessive and worked to change it.','他反复检查锁门逐渐成了一种轻微的神经质表现，尽管他知道这个习惯过度并努力改变。','His repeated checking of the locked door became a minor neurosis / though he knew the habit was excessive / and worked to change it.','neurosis 也可非正式指日常生活中的紧张或过度担忧行为。','反复检查且本人知道过度，体现日常忧虑行为。')],M('The old case note used neurosis for a person’s calm, proportionate response with no anxiety or unreasonable fear.','The old case note used neurosis for persistent anxiety and unreasonable fears.','没有焦虑或过度恐惧的平静反应不符合该词的历史用法。','meaning'),[q('What did the older case note describe?','persistent anxiety and unreasonable fears','a smooth-skinned peach','a railway network','旧病历用该词描述持续焦虑和恐惧。'),q('What habit became a minor neurosis?','repeatedly checking a locked door','checking the door once before leaving','repairing a neural pathway','反复确认锁门成为过度担忧行为。',2),q('How should the historical term be treated?','as an older label, with a modern assessment specifying the diagnosis','as the only current diagnosis for every anxious person','as a term for a nerve cell','source notes it is older language; current assessment should be specific.',1,'register'),q('In everyday use, neurosis may refer to?','nervous or unreasonable worry in behaviour','a nerve’s normal signal','a nearby place','日常义指紧张或不合理的担忧表现。',2,'distinction')]);
P('neurospora','Neurospora is a scientific genus name built from Greek neuro- (“nerve-like”) and spora (“spore”); it names a mould used in gene and enzyme research.',C('neurospora.s1','模式真菌','Researchers used Neurospora in experiments showing how genes relate to enzyme production in fungal cells.','研究人员用脉孢菌进行实验，揭示基因与真菌细胞中酶生成之间的关系。','Researchers used Neurospora in experiments / showing how genes relate / to enzyme production in fungal cells.','Neurospora 是一种霉菌属名，曾用于基因与酶的研究。','研究以该真菌实验理解基因如何影响酶。'),M('The laboratory identified Neurospora as a mammal used for experiments on bird migration.','The laboratory identified Neurospora as a mould used in gene-and-enzyme experiments.','Neurospora 是真菌，不是哺乳动物。','meaning'),[q('What did researchers study using Neurospora?','the relation between genes and enzyme production','how a motorway crosses a county','how a necklace is fastened','研究用脉孢菌探索基因与酶生成的关系。'),q('Neurospora is a?','mould','mammal','noble gas','Neurospora 是一种霉菌。',1,'meaning'),q('Which project fits the example?','testing how genes affect enzyme production in a fungus','tracking a nephew’s family tree only','measuring a nearby road’s width','真菌基因与酶实验符合例句。',1,'context'),q('What do neuro- and spora suggest in the name?','nerve-like and spore','new and stone','need and work','属名构件与“神经状”和“孢子”相关。',1,'word-formation')]);
P('neurotic','Neurotic is formed from neuro- and -tic and describes a tendency to anxiety or obsession; as a noun for a person it is older psychiatric language.',[C('neurotic.s1','焦虑倾向','He became neurotic about checking the laboratory locks, returning to the door several times even after seeing it secure.','他对检查实验室门锁变得过度焦虑，即使确认已锁好仍返回查看好几次。','He became neurotic about checking the laboratory locks / returning to the door several times / even after seeing it secure.','neurotic 作形容词可形容焦虑、强迫或情绪不稳定的倾向。','反复确认已锁好的门显示过度担忧。'),C('neurotic.s2','旧式名词用法','The older novel calls a character a neurotic, but a modern editor replaces the label with a description of the person’s specific symptoms.','旧小说把一个人物称作 neurotic；现代编辑则改用对其具体症状的描述。','The older novel calls a character a neurotic / but a modern editor replaces the label / with a description of the person’s specific symptoms.','旧式心理学语言中 neurotic 可作名词指有神经症的人；现代写作宜具体描述。','编辑避免用过时标签，改写具体症状。')],M('The editor called the character neurotic because she calmly checked the lock once and showed no anxiety or repeated worry.','The editor described her as neurotic because she repeatedly checked a secure lock from excessive worry.','一次平静检查不体现过度焦虑或反复强迫。','meaning'),[q('What did he repeatedly check?','the laboratory locks','a net’s knots','the clinic’s nectar supply','他反复检查实验室门锁。'),q('Why did he return to the door?','he was excessively anxious despite seeing it secure','it was a necklace shop','the lock was a neuron','他明知已锁好仍因过度担心而返回。',1),q('Why does the modern editor replace the noun label?','it is older language and specific symptoms are clearer','it is the name of a neural cell','it means “nearly complete”','旧式人称标签不如具体症状描述清楚。',2,'register'),q('Which behaviour is most clearly neurotic in the anxiety sense?','rechecking a secure lock many times from excessive worry','checking a lock once before leaving','installing a new lock','反复过度检查体现焦虑或强迫倾向。',1,'context')]);
})();
